            values: new object[,]
            {
                { 3485, "Ageage Again (Module)", "Ageage Again", "REO OBATA (SQEX)", "/miku_monday/Ageage Again (Module).png", "The Module's attire consists of black headphones with greyish-gold on the ear-pads, a white sleeveless crop-top with black square designs, black arrows, and an upside-down V-cut on the bottom, a white collar with black rims, fuzzy black cuffs, short shorts held with a white belt, a black walker with a green belt strap, black boots with yellow soles with a small stripe on the center, and black and greyish-gold futuristic ribbons. Additionally, Miku's hair becomes yellowish-green with an infinite number of \"plus\" pieces splitting off and disappearing from her twin pigtails, and her nose-bang and hair fringes become slightly thinner. In Arcade Future Tone, its PlayStation 4 port, and MegaMix, she wears green eyeliner.", "[\"Ageage Again\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3158, "Agitation", "Agitation", "Nagimiso", "/miku_monday/Agitation.png", "The Module's attire consists of grey headphones with red dials on the earpads, and thick gold plates on both sides of the handle, a cropped jacket with differing tones of grey, a heart design on the left side and on the entire back, a zipper, a gold trimming on the neck, and black sleeves, a V-cut undershirt with a garter connecting to the boots, a red and black armband with a heart design on the left arm, small gold designs on the sleeves, black gloves with wowaka's logo in red, an additional black undershirt, a black skirt with gold designs held with a black belt, grey stockings with darker patterns, and thigh-high black boots with gold soles. Additionally, Miku's hair becomes pale green, her bangs become shorter, and her eyes become yellow.", "[\"Unhappy Refrain\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3078, "Aile d'Ange", "Aile d'Ange", "Shinrei", "/miku_monday/Aile d'Ange.png", "The Module's attire is different to that of Miku's original module is that it consists of black circular headphones with an attached mic on the right earpad, a white crop-top with black trimmings and laces, matching detachable sleeves, a white skirt with black trimmings and black and white belts, long white stockings held by a black garter, silver cuffs with white stripes on the ankles, white shoes with black soles, and black ribbons tied on Miku's twin tails. Additionally, her hair and eyes become a silvery white, her nails become gray, and she has a small pair of black angel wings tattoo on her back.", "[\"VOiCE\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7481, "Akaku Sweet na Hana", "Akaku Sweet na Hana", null, "/miku_monday/Akaku Sweet na Hana.png", "The Module consists simply of a bouquet of red sweet peas, held with pink and white wrapping that is tied with a red ribbon.  Miku's Module Fairy is used as a base for this Module.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 6876, "Akikaze", "Akikaze", "Yuichirou Kojima", "/miku_monday/Akikaze.png", "The Module's attire consists of magenta headphones with a black handle and yellow stripes and blue and white stars on the earpads, a light-green cardigan that is loosely worn and only buttoned on the top, an olive-green tank top with white straps and black stripe on the bottom hem, a gold necklace with a blue and grey pendant, a dark-pink pleated skirt, black tights, orange shoes with a yellow stripe and black soles, and a pale red scrunchie with medium accents. Additionally, Miku's hair becomes shorter, puffy, and spiky, it is tied up in a right-side ponytail, and she has thick bangs swept to the left.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4044, "Ambivalence", "Ambivalence", "Ho4ma", "/miku_monday/Ambivalence.jpg", "The Module consists of scarlet circular headphones with a black handle, magenta illumination, and an attached mic on the left earpad, a greyish-brown short top with a red bow attached and a sparkly red choker, along with long red gloves reaching just below the shoulders, and with black lines the the sides of the gloves, and the top of the gloves are black. It includes a red cape-like skirt revealing one leg and reaching the ankles, and with black outlining the skirt along with a red bow on one side and a silver belt. On the right leg is a red and greyish-brown ribbon and a crossed heart tattoo. The shoes are red high heels with a straps on the ankle and lines from the straps to the toes of the heels.  The facial appearance includes deeper and darker blue hair and irises with the twin tails being slightly thinner and tied with red bows on each side and her bangs matching Megurine Luka's. There is also a crossed heart tattoo on the left cheek just below the eye.", "[\"Brain Revolution Girl\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3098, "Americana", null, "exiled_artist", "/miku_monday/Americana.png", "The Module's attire consists of lightest grey headphones with a blue star-shaped mic, and dark blue rectangles on the earpads, a short white jacket with blue sleeves and collar, and red streamers on the edges, a red choker, a short blue crop top tied into a bow at the center, a white skirt with red streamers on the bottom edges held with a blue belt that features silver star designs, white heeled boots with red streams on top, and blue star-shaped hairbands.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3082, "Angel", "Angel", "Tomio", "/miku_monday/Angel.png", "The Module's attire consists of a white A-neck one-piece dress with teal trimming and a teal F-clef (Bass-clef) design on the back, light-teal frilled balloon shorts, a necktie with a dark blue and deep pink tie clip and light blue trimming and a teal string, white gloves with cuffs and teal bracelets, a teal choker, long white socks with teal designed trimmings and light blue patches on the knees, light blue Mary-Jane high-heels with angel wings on the heels, turquoise circular headphones with angel wings on the earpads, and has angel wings on Miku's back. Additionally, she wears her hair loose that becomes separated into being pigtail-like.", "[\"The First Sound\",\"Innocence\",\"Electric Angel\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 6791, "Animal Fortune-telling (Outfit)/Miku", "Animal Fortune-telling", "matutori", "/miku_monday/Animal Fortune-telling (Outfit)/Miku.jpg", "The Outfit's attire features a koala motif, consisting of a light green sequin dress with orange, yellow, and white hues (referencing the backgrounds in the PV for \"Animal Fortune-telling\"), pink inner fabric, and two pink buttons on the back, a white fluffy vest with a large puffball holding it together in front and a pink bow on the back, white scrunchies on her wrists, white pumpkin pants, white stockings, and pink shoes with white puffballs and soles. Additionally, Miku wears her hair in twin-buns with two large puffballs perched in front of each bun, resembling koala ears.", "[\"Animal Fortune-telling\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4035, "Anode Electronica", "Anode Electronica", "fuzichoco", "/miku_monday/Anode Electronica.jpg", "The Module's attire consists of a short, black, cybertronic coat with turquoise accents and pink diamond decorations on the chest area, matching detachable sleeves, and a light turquoise sash around the waist decorated with pink heart ornaments on the ends. There is also wears a white opened, shirt, a black bra, a black skirt that goes into turquoise, and black boots with turquoise accents with a heart on the sides of the heel. Additionally, Miku wears a pink and black heart-shaped hairpieces with which her twintails, along with pink accents, goes through.", "[\"Ai Dee\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3014, "Arabian", "Arabian", "inakayaki", "/miku_monday/Arabian.png", "The Module's attire features an Arabian theme. It consists of a purple crop top that has X-shaped gold armor embedded on it, and a matching armor plate in the lower section that appears to be a belt, an armored choker, two white ornaments with blue jewel pieces on each shoulder, detachable black sleeves with wrist jewelry, red pants, a dark pink veil sticking out of the pants, black and gold sandals, and a jeweled piece hanging in the center of Miku's forehead and a headpiece of precious stones.", "[\"Velvet Arabesque\",\"Catch the Wave\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3248, "ARIFURE Miku", "ARIFURE Miku", "Edielec", "/miku_monday/ARIFURE Miku.png", "The Module's attire consists of a white short-sleeved shirt, a navy blue striped long-sleeved undershirt, a long red scarf with white stripes, short yellow shorts with light-yellow rims, navy blue stockings with matching socks, yellow boots with fluffy light-yellow cuffs, and yellow ribbons tied on Miku's twin-tails. Additionally, her hair, eyebrows, and nails become cerulean, her hair also becomes wavy and extends down to her midsection, her bangs have three sections that become shorter, and she wears cerulean mascara and a bandage on her nose.", "[\"Arifureta Sekai Seifuku\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7582, "Arle", "Arle", "SEGA", "/miku_monday/Arle.jpg", "Miku's Outfit is based off the character Arle Nadja from the [https://puyonexus.com/wiki/Puyo_Puyo PuyoPuyo] series. It consists of a white T-shirt with double-V cuts on the front, a blue breastplate held with a gold rim with matching shoulder plates connected on, a blue cape with a white rim and red inner fabric, long, white wristbands with blue rims, a blue skirt, and blue boots with white cuffs, straps, and soles. Additionally, the stripes on Miku's hairbands become blue.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3239, "Avant-garde", "Avant-Garde", "Kuuma", "/miku_monday/Avant-garde.png", "The Module's attire consists of a cropped teal jacket with puffed upper-arms, black stripes on the hems, a large black hem on the top with teal stripes, and black cuffs, a brown waist belt, a white sleeveless turtleneck dress with turquoise hues and frills, and a black collar, dark stockings, black socks, and brown boots with light brown stripes with buttons, and white soles. Additionally, Miku's twin-tails are held with black hairbands.", "[\"Akatsuki Arrival\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4040, "Bandaged Heart", "Bandaged Heart", "gagame", "/miku_monday/Bandaged Heart.jpg", "The Module's attire consists of a short black open-collared jacket with white bandages wrapped around the sleeves, a black necktie, a white top covered entirely in bandages with red lining on the top part and a white bow tied on the back, bandages wrapped around the hands leaving the fingers exposed, black pants with bandages wrapped around, and white shoes with red soles. Additionally, Miku's hair becomes dark green that bleeds into red towards the bottom and the upper part has bandages wrapped around, there is a big heart headpiece covering the right side of her head, and her eyes become dark red.", "[\"Streaming Heart\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3256, "Breathe With You", "Breathe With You", "Siracomgi", "/miku_monday/Breathe With You.png", "The Module's attire consists of a white frilled crop top with a black and red collar, black frilled cuffs with white edges that are tied with red strings, a black and red frilled skirt with a black bow on the back with four diamond-shaped strings, a small red belt, black and red thigh-high boots with matching bows on the back, and a large white corsage. Additionally, Miku's hair gains a partial black hue.  In Project DIVA Arcade Future Tone, its PlayStation 4 port, and Project DIVA MegaMix, Miku's bangs are now parted to the right.", "[\"Two Breaths Walking\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4050, "Brilliant Butterfly", "Brilliant Butterfly", "Shizuka Kitajima (ELECTROCUTICA)", "/miku_monday/Brilliant Butterfly.jpg", "The Module includes a dark purple dress turning into pink and silver at the end, a white collared shirt with frills on the chest and a purple gem on the neck, and a white tail and purple bow on the back of the dress. It also includes dark purple gloves reaching to just under the shoulder, the right glove also being fingerless, dark purple thigh-high stockings that bleed into light purple and white cuff openings, and dark purple Mary-Jane high heels.  The facial appearance includes three long purple twin drills that bleed into turquoise and are held with silver hairbands, as well as Miku's eyes becoming purple, her bangs thicken resulting two additional strands, and her wearing nail polish.", "[\"Elegant Medley - Glossy Mixture\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3689, "Bunny Ears Hoodie", "Bunny Ears Hoodie", "Nyami", "/miku_monday/Bunny Ears Hoodie.png", "The Module's attire consists of a light-pink, one-piece parka with a bunny motif, complete with brown button eyes, an orange X-stitch in place of a nose, bunny ears with pink canals, a blue bowtie, brown buttons, a pink rabbit patch, and a tail on the back, purple and white striped stockings and white bunny slippers.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3170, "Cabin Attendant Hatsune Miku", "Cabin Attendant Hatsune Miku", "Asahi", "/miku_monday/Cabin Attendant Hatsune Miku.png", "The Module's attire consists of a white speaker with an attached mic and a purple music note design on the earpad on the left ear, a turquoise attendant's cap with a gold star, a turquoise and white horizontally striped dress with two yellow buttons on the center chest area, and two small triangular-cuts on the front sides, revealing a teal fabric, a teal waist belt with a silver circle-shaped buckle, a red ascot, white gloves with red edge trimmings on the cuffs, dark leggings, and teal flats. Additionally, Miku's twin-tails are significantly shortened to shoulder-length.", "[\"Tricolore Airline\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4205, "Cabin Attendant Style 39", "Cabin Attendant Style 39", null, "/miku_monday/Cabin Attendant Style 39.jpg", "The Module is based off the standard stewardess uniform for the Japanese regional airline, AIRDO. It consists of a dark navy-blue blazer with blue, white and yellow stripes on the edges of the sleeves, a matching skirt, a white, collared shirt, black stockings and shoes, and a yellow and blue ascot.  This alternate version of Cabin Attendant Style A features Miku with her iconic twintails that are held with blue, white, and yellow versions of her futuristic hairbands.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2384, "Cabin Attendant Style A", "Cabin Attendant Style A", null, "/miku_monday/Cabin Attendant Style A.jpg", "The Module is based off the standard stewardess uniform for the Japanese regional airline, AIRDO. It consists of a dark navy-blue blazer with blue, white and yellow stripes on the edges of the sleeves, a matching skirt, a white, collared shirt, black stockings and shoes, and a yellow and blue ascot. Additionally, Miku's hair is wrapped in a bun and her front bangs are parted to the right with a hairclip.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4034, "Cantatrice", "Cantatrice", null, "/miku_monday/Cantatrice.jpg", "The Module's attire consists of a white and lavender cropped dress, a lavender detachable collar, light lavender frilled shorts, purple fingerless gloves with laces on the lower arms, matching Mary-Jane ballet slippers with laces on the legs that fade into lavender, and white lilies on the left side of Miku's hair. Additionally, her hair becomes dull turquoise and is braided into a left-side ponytail that is slightly short, her bangs are parted to the left, and her eyes and fingernails become lavender.", "[\"Name of the Sin\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3362, "Catch the Wave (Module)", null, "LAM", "/miku_monday/Catch the Wave (Module).png", "This Module consists of Miku wearing a black collared white cropped top with large colourful (black, cerulean, yellow and hot pink) frills spilling out from the left hand side and a matching white and black skirt with more colourful frills spilling from her right hip. She also wears grey fingerless gloves with a spikes rainbow colored bracelet which is a similar design to her two hair ties which replaces her signature black and red square like ties. Her hair and eyes are still turquoise but with a slightly lighter shade and with the hair large streaks of neon green in her twintails, her bangs are also cut to a fringe, and to finish it off, she has a yellow clip in a shape of a 'C' with an arctic blue center. There are also long white loose socks and black and hot pink sneakers with yellow laces with small multicoloured balls inside the soles. Additionally, Miku wears hot pink eyeshadow and two painted hearts on her face, with the left one on her cheek a tiny hot pink and on the top right a small cerulean.", "[\"Catch the Wave\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3723, "Celebration", "Celebration", "Mari Shimazaki", "/miku_monday/Celebration.png", "The Module's attire is a more stylized version of Miku's default outfit. It consists of a multicolored sleeveless collared shirt, a white see-through necktie with turquoise hems and a yellow star, black see-through detachable sleeves with turquoise hems, a black skirt with turquoise parameters, a bright multicolored hem, and a belt-chain, black see-through boots with turquoise cuffs and multicolored heels, and a large bow resembling a music staff on the back. Additionally, her hair remains turquoise while having different multicolored strands, her twin tails are tied with hairbands resembling the ones from her default outfit, albeit with a more striped pattern, and each of her fingernails are painted in different colors.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3235, "Chat Noir", "Chat Noir", "tohma", "/miku_monday/Chat Noir.png", "The Module's attire consists of a jet black school uniform, which includes a blouse with white trimmings and a purple cat design on the back, a red scarf, a jet black skirt, black leg-length socks, jet black loafers, a brilliant azure cat paw with brilliant scarlet pads and white claws on the left hand, and black cat ears with red canals. Additionally, Miku's hair becomes jet black with a portion resting on her left shoulder like Megurine Luka and a short portion on the right, her bangs are horizontally cut, and her eyes become dark grey. She never wears nail polish.  In F 2nd and X, her hair becomes dark grey, and in MegaMix, the cat paw becomes a pale cyan with moderate amaranth pads.", "[\"Envy Cat Walk\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3237, "Chat Noir Alt.", "Chat Noir Alt.", "tohma", "/miku_monday/Chat Noir Alt..png", "The Module's attire consists of a jet black school uniform, which includes a blouse with white trimmings and a purple cat design on the back, a red scarf, a jet black skirt, black leg-length socks, and jet black loafers. Additionally, Miku's hair becomes jet black with a portion resting on her left shoulder like Megurine Luka and a short portion on the right, her bangs are horizontally cut, and her eyes become dark grey. She never wears nail polish.  In F 2nd and X, her hair becomes dark grey.  This alternate version of Chat Noir removes the cat ears and the cat paw from her left hand.", "[\"Envy Cat Walk\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3174, "Cheerful Miku", "Cheerful Miku", "bun150", "/miku_monday/Cheerful Miku.png", "Miku's Module is based off the outfit featured on Good Smile Company's \"Hatsune Miku Cheerful Ver.\" figurine released in 2011. It consists of a light yellow crop top with orange trimmings and see-through fabric in the center chest area, a light yellow detachable collar, a light purple tie, light yellow detachable sleeves, a black skirt with small light purple and orange stripes, orange see-through fabric connected to the back of the skirt, black diagonally-cut spandex that cover from the thighs to the upper calves with light purple stripes on sides, orange boots with white circles featuring orange hearts, black cuffs, and orange see-through soles, and see-through material connected to the back of the cuffs. Additionally, Miku's twin-tails are held with black and purple bows with three strands of hair sticking out on each twin-tail, and some of her bangs are parted to the right.", "[\"SING&SMILE\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3180, "Cheerful Miku Alt.", "Cheerful Miku Alt.", "bun150", "/miku_monday/Cheerful Miku Alt..png", "Miku's Module is based off the outfit featured on Good Smile Company's \"Hatsune Miku Cheerful Ver.\" figurine released in 2011. It consists of a light-yellow crop top with orange trimmings and see-through fabric in the center chest area, a light-yellow detachable hood-like collar, a light-purple tie, light-yellow detachable sleeves, a black skirt with small light-purple and orange stripes, orange see-through fabric connected to the back of the skirt, black, diagonally-cut spandex that cover from the thighs to the upper calves with light-purple stripes on sides, orange boots with white circles featuring orange hearts, black cuffs, and orange see-through soles, and see-through material connected to the back of the cuffs. Additionally, some of her bangs are parted to the right.  This version of Cheerful Miku has her hair put in twin buns that are held with black and light purple bows.", "[\"SING&SMILE\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2964, "Cheerleader", "Cheerleader", "Hisakawa", "/miku_monday/Cheerleader.png", "The Module's attire consists of a cheerleader styled motif with includes a pink shirt with a white heart design with the  piapro logo printed on, white trimming, a blue tank top underneath the shirt, a star on the left shoulder, a pink pleated skirt with white, yellow, and blue trimming, white socks with leeks printed on opposite sides, pink high top sneakers with white laces, tips, and soles and the piapro logo printed on the tongue, white and blue wrist cuffs, and a pink sun visor with a blue brim and the piapro logo printed on the front strap. Additionally, Miku's twin-tails are significantly shorter.", "[\"Dear cocoa girls\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2153, "Chinese Debut", "Chinese Debut", "shinryo rei", "/miku_monday/Chinese Debut.png", "The Module's attire consists of a Chinese theme to it. Instead of wearing knee-high leggings, Miku wears black pumps with thigh high white socks. She also has a more wavy skirt and a cheongsam-styled gray shirt that lacks her iconic tie. A notable accessory to the Module is the stuffed panda on her back. In Hatsune Miku: Project DIVA Arcade and F 2nd, her signature twin-tails are thinner following the improved visuals of those games over the PlayStation Portable games. The panda accessory can also move its left arm in said F game and X.  In the Project DIVA Arcade series, its PlayStation 4 port, the Dreamy Theater series, and MegaMix, dark gray flower and bird patterns are added to the shirt.", "[\"Updating My Love List?\",\"One-Sided Love Samba\",\"Wolf Girl\",\"Electric Angel\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4037, "Chopstick", "Chopstick", "Nagimiso", "/miku_monday/Chopstick.jpg", "The Module's attire consists of a white coat with grey stripes on the sides, a gold zipper and teeth, red puffy sleeves and gloves with white palm, hexagonal patterns on the bottom, and a gold bug-like contraption with green lights on the back. There is also a large, light-green skirt with white hexagonal patterns, and red leggings and boots. Additionally, Miku's hair becomes teal, her bangs are horizontally cut, her twintails are horizontally cut on their bottoms and are of varying lengths, her eyes become light-green, she wears a black mask, and she wears a light-red helmet with white pentagonal patterns and has gold coverings that cover the ears chin and the back of the head and include extended antennas.", "[\"Babylon\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 6807, "Clover♣Club (Outfit)/Miku", "Clover♣Club", "tamajam", "/miku_monday/Clover♣Club (Outfit)/Miku.jpg", "The Outfit's attire consists of a black striped work blouse with puffed sleeves and white cuffs, a white collar with a pink bow tied on, a cropped black vest with white trims and a gray tag on the left side, a white apron with lace designs on the trims, a black striped skirt that also has lace on the trim, brown stockings with diamond patterns, and black Mary-Jane pumps. Additionally, Miku's hair becomes light jade green, her bangs are parted to the right with a hairclip that has clover on it, and she wears a black head wrap with openings for her twin-tails.", "[\"Clover♣Club\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3035, "Colorful Gumdrop", "Colorful Gumdrop", "nezuki", "/miku_monday/Colorful Gumdrop.png", "The Module's attire consists of white earphones, a pink flower clipped to Miku's left pigtail, a mint green one-piece balloon dress with vertical black stripes, a very light cerise bow at the top center, and frills at the bottom, long tangelo socks with tan ribbons, dark aquamarine strapped shoes, and white fluffy detachable sleeves. Additionally, her twin-tails are shorter and wavy with sections of it in hairband form.", "[\"Colorful × Melody\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3504, "Conductor Nightingale", "Conductor Nightingale", "Chiho", "/miku_monday/Conductor Nightingale.png", "The Module's attire consists of a brown, collared conductor jacket with an upside-down V-cut on the bottom, olive trims on the cuffs and cuff links, five buttons, and a white emblem on the back of the jacket with her serial code \"01\". There is also a brown pleated skirt, dark pantyhose, and black high heels. Additionally, Miku's hair becomes an olive green, her twintails become more thinner, has side hair that extends down to her mid-section, and has a white flower with bows in her hair with additional small flowers on her twintails. She also wears a brown conductor's hat with light-brown rims, and a gold emblem with a  kanji symbol embedded.  In Project DIVA Arcade Future Tone, its PlayStation 4 port, and Project DIVA MegaMix, Miku's irises become brown and her eyebrows become the same olive green as her hair.", "[\"1925\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3092, "Conflicted", "Conflicted", "redjuice", "/miku_monday/Conflicted.png", "The Module's attire consists of a mismatching black and white sweater and skirt reminiscent of the yin-yang. The yin-yang motif is more apparent with an emblem stitched on the left side of the shirt. There are also matching buns that hold Miku's twin-tails with two plates on each bun, a black undershirt, white socks, and black shoes with small white laces. Additionally, her hair, eyes and eyebrows become darker teal and her bangs have three pointed parts that become slightly shortened and are parted to the left.", "[\"Two-Sided Lovers\",\"World's End Dance Hall\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4806, "Convenience Style C", "Convenience Style C", null, "/miku_monday/Convenience Style C.jpg", "The Module's attire is based off the standard uniform for the store chain Circle K Sunkus. It consists of a red and blue, collared shirt with the company logo on the right breast, a white, collared undershirt with a teal tie, a red, yellow, and blue wristband on the left wrist, a white skirt, and black stockings and loafers.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4805, "Convenience Style F", "Convenience Style F", "putidevil (''Project DIVA F'')", "/miku_monday/Convenience Style F.jpg", "The Module's attire is based off the standard uniform for the store chain Family-Mart. It consists of a black collared shirt with a FamilyMart logo on the collar, a white undershirt, a turquoise tie, and a white skirt.  In Project DIVA Extend and Live Stage Producer, Miku wears a green, white, and light-blue wristband on her left wrist, black stockings, loafers, and a headset, while in Project DIVA F, she wears white thigh-high boots with blue cuffs and soles, a green hem is added to the skirt, the wristband and headset are removed, and her futuristic hairbands become white and green.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2305, "Convenience Style L", "Convenience Style L", null, "/miku_monday/Convenience Style L.png", "The Module's attire is based off the standard uniform for the store chain Lawson. It consists of a blue and white striped shirt with the store name on the right side, a white undershirt with a teal necktie, a white skirt, a blue, white, and red wristband on her left wrist, long black stockings and shoes.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4787, "Convenience Style S", "Convenience Style S", null, "/miku_monday/Convenience Style S.jpg", "The Module's attire is based off the standard uniform for the store chain 7-Eleven. It consists of a red and pink, collared shirt with the company logo on the right breast, a yellow, green, and red wristband on the left wrist, a white skirt, and black stockings and loafers.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7525, "Cyber Rock", "Cyber Rock", null, "/miku_monday/Cyber Rock.png", "The Module consists of a white cropped school shirt with a black collar with magenta stripes, matching sleeve cuffs, and a teal ascot, a pleated skirt that matches the collar and cuffs, black fingerless gloves, a magenta and teal bracelet, gray stockings with piano designs on the sides, and dark-gray shoes. Additionally, Miku's hair becomes more rugged with her twin tails reaching shoulder-length and has spiral-like buns tied with magenta ribbons that also include flaps that lay over them.  She also wields a turquoise guitar held with a dark-teal triangular patterned strap that goes over her shoulder.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2979, "Dancer", "Dancer", "Botamochi", "/miku_monday/Dancer.png", "The Module's attire consists of a dark grey sleeveless cropped shirt with turquoise trimmings, a black cropped tank top underneath the shirt, black pants with turquoise trimmings throughout, matching fingerless gloves with bracelets that resemble Miku's futuristic hairbands, a teal belt with matching belt chain, and black shoes with turquoise soles.", "[\"Far Away\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3188, "Dark Angel", "Dark Angel", "SEGA", "/miku_monday/Dark Angel.png", "The Module's attire is a gothic-lolita dress that consists of a jet black collared dress shirt with white lace on the sleeves and frilled cuffs, a white collared undershirt with a jet black tie, a jet black skirt with a white lace and frilled layers, thigh-high socks with white stripes, platform boots with three belts on each boot and dark blue laces, and feather clips attached to the hairbands. Additionally, Miku's hair, eyes, eyebrows, and nails become a strong sea green and her twin-tails become more drilled shaped, similar to Kasane Teto, though Miku's drills are longer, her fringe becomes a bit messy, and her nose-bang becomes slightly thickened and is pointed down with two thin strands.  In Project DIVA MegaMix, the laces become a lighter shade.", "[\"Secret Police\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4030, "DE:MONSTAR", null, null, "/miku_monday/DE:MONSTAR.jpg", "The Module's attire consists of a red eyepiece around the left eye, a red smaller eyepiece below the right eye, a lime green top with the left side mostly missing, a black one-shoulder tank top, red gloves with lime green palms and spikes on the cuffs, a light yellow frilled skirt with a red and white bow tied around, a red demon tail with a white stripe on the tip, gray stockings with lime green circles, and red high-heels with lime green straps and silver heels. Additionally, Miku's twin-tails are held with red demon horns and her bangs lengthen.", "[\"Satisfaction\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3152, "Deep Sea Girl (Module)", "Deep Sea Girl", "haruyo (ODESSA)", "/miku_monday/Deep Sea Girl (Module).png", "The Module's attire consists of a black dress with a skirt-like bottom layer, a sea-foam lace on the right shoulder, and a calf-length layer on the right side of it, and black kelp-like hairbands. Additionally, Miku's hair and eyes become a sea blue with her hair and bangs becoming thicker and wavier.", "[\"Deep Sea Girl\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3182, "Deep Sky", "Deep Sky", "Nidy-2D-", "/miku_monday/Deep Sky.png", "The Module's attire consists of red under-rim glasses, a sky blue V-cut school sweater with two yellow stripes on the left sleeve and a small emblem, a white collared undershirt, a brilliant amaranth plaid necktie, a black plaid skirt, matching socks and loafers, and red hairbands (like her floating futuristic ribbons). Additionally, Miku's twin-tails reach to her thighs and become wavy, and her bangs have an extra layer.", "[\"Monochrome∞Blue Sky\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3094, "Demons and the Dead", "Demons and the Dead", "Hachi", "/miku_monday/Demons and the Dead.png", "The Module's attire consists of a kitsune mask on top of the left head, a black kimono with dark yellow designs of wheat held by a red, tan, and white obi sash and belt, and black sandals with brick red straps. Additionally, Miku's skin becomes pale white, has eyes painted on her hands, her eyes become red, her hair becomes black with red and dark-green hues, and her fingernails are painted red.", "[\"Close and Open, Demons and The Dead\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7485, "Densetsu no Junpaku Mic", "Densetsu no Junpaku Mic", null, "/miku_monday/Densetsu no Junpaku Mic.png", "The Module consists simply of a white Shure SM58 microphone.  Miku's Module Aile d'Ange is used as a base for this one.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3241, "Dimensional", "Dimensional", "BUZZ", "/miku_monday/Dimensional.png", "The Module's attire consists of black headphones with neon pink lighting and wires with white jacks on the ends, a white and grey sleeveless collared shirt with an opening on the upper-chest area, black plates attached on top of the bottom half, and extended flaps on the back, long black gloves with floating neon pink armbands, Miku's serial number \"01\" printed in red above her left breast, a neon pink bow on the back of the shirt, shorts that match the shirt, a neon pink band on the right thigh, white legwarmers with black hems, and black high-heels with neon pink heels. Additionally, Miku's hair becomes slightly darker turquoise, her twin-tails are thinner and the endpoints are diagonally cut, and her pupils become pink.", "[\"2D Dream Fever\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3229, "Divine Goddess", "Divine Goddess", "Han'nya G", "/miku_monday/Divine Goddess.png", "The Module's attire consists of a halo-like tiara with pleats of fabric on the sides, gold triangular earrings, a white short crop top, a matching short overcoat that exposes the left shoulder, a fluffy see-through collar, and a floor-length skirt with a slit on the right side and a gold hem. Additionally, Miku's twin-tails are braided to be rope-like, with Project DIVA F, F 2nd and X having gold hair bands, and also tied with a bow-shaped bun on the back, and a giant halo floats behind her.  In Arcade Future Tone, its PlayStation 4 port, and MegaMix, her hair becomes a greyish sea green with turquoise hues on the bottom, and MegaMix has her eyebrows become green.", "[\"God-Tier Tune\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7550, "Doremifa Rondo (Outfit)", "Doremifa Rondo", "Tama", "/miku_monday/Doremifa Rondo (Outfit).jpg", "The Outfit's attire consists of a blue shako cap with white in the middle and a light blue eighth note (♪) printed on it, a black brim, and gold stripes on the vinyl and brim, a light-blue marching band jacket with puffed shoulders, gold stripes, a white middle section with gold epaulets, a sky-blue and black striped sash held with a gold link, white gauntlets with gold stripes and cufflinks, a black, pleated skirt, long, blue stockings with gold stripes on each side, and black shoes. Additionally, Miku's hair becomes a sky blue with lighter streaks and her twin-tails become slightly thinner and are held with blue bands.", "[\"Doremifa Rondo\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3140, "Dreamer", "Dreamer", "akka", "/miku_monday/Dreamer.png", "The Module's attire consists of gold beaded earrings, a black collared crop top with front pockets, a tan fur collar tied with a white bowtie, a red cape, white frilled cuffs, a light yellow frilled skirt, black socks, and white rolled-up boots. Additionally, Miku's twin-tails are tied at the back bottom of her head with a portion of it in hairband form, and her hair and eyes become lighter turquoise.", "[\"Yumeyume\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7566, "Electric Angel (Outfit)/Miku", "Electric Angel", "Agatha", "/miku_monday/Electric Angel (Outfit)/Miku.jpg", "The Outfit's attire consists of a white, sleeveless coat with V-cuts on the bottom, a matching sleeveless, collared shirt with a black collar, a blue necktie, and pink hearts printed down the center, black gloves with petal cuffs, angel wings on the back, a black skirt with additional pink and blue layers, black boots with blue soles, and dark-pink headphones with white heart and wing designs on the earpads and angel wings on the sides of the handle.", "[\"Electric Angel\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7564, "Electric Love (Outfit)", "Electric Love", "Aco Arisaka", "/miku_monday/Electric Love (Outfit).jpg", "The Outfit's attire consists of a luminous, sleeveless magenta collared shirt with triangle, circle, and square plates attached to the left side of the chest, a black necktie with a white heart printed on, a black, pleated skirt with white hems, and black boots with mismatching magenta and teal hems and soles. Additionally, Miku's hair gains pink hues on her bangs, twin-tails, and cowlick, her twin-tails are decorated with triangles, circles, and squares, wears a yellow heart hairpin on her left fringe, her hairbands' stripes alternate between magenta and blue, and her eyes have small, yellow hearts and slight pink hues in the irises.", "[\"Electric Love\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4036, "Engage", "Engage", "toi8", "/miku_monday/Engage.jpg", "The Module's attire consists of a greyish pink futuristic dress coat with dark blue hues on the bottom, pinkish-red cuffs and armbands, light-blue accents, three large brown buttons, and a white waist belt with a pinkish-red stripe, a white skirt with a black stripe, black stockings with light grey triangular trimmings, high-heeled sandals with a satin bow, silver and orange headphones, and glasses. Additionally, Miku's twin tails are slightly shortened and curved and gain cerulean hues, her fingernails become the same hue color, and her toenail polish is removed.", "[\"Calc.\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3487, "Etoile", "Etoile", "Sayopon (SEGA)", "/miku_monday/Etoile.png", "The Module's attire consists of a red frilled tutu with black laces, translucent bow, and skirt layer, red detached cuff sleeves on the upper arms, and red pointe shoes. Additionally, Miku's twin-tails become shoulder length and are curled, has horizontally cut bangs, and wears a red corsage with black ribbons on the left side of her hair.", "[\"Gaikotsu Gakudan to Riria\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3233, "Factory Tyrant", "Factory Tyrant", "[[cosMo@BousouP]]", "/miku_monday/Factory Tyrant.png", "The Module's attire consists of a black peaked cap hat with a turquoise stripe and a silver plate with black musical notes on it, a black dress with turquoise trimmings and buttons, and a CD on the bosom, long matching gloves with cogwheels floating around the wrists, and matching boots that also have cogwheels floating around the ankles. Additionally, Miku's eyes become red, has a small cogwheel tattooed on the left side of her face, and silver cuffs connected to her twin-tails.  cosMo's illustration for \"Sadistic.Music∞Factory\" shows underneath Miku's dress, which reveals black shorts held with a turquoise belt with keys attached on the side, and Miku's torso being a see-through tube with two cogwheels forming an infinity symbol floating in the center.", "[\"Sadistic.Music∞Factory\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3006, "Fairy", "Fairy", "GAOGAO", "/miku_monday/Fairy.png", "The Module's attire consists of a white dress that becomes ragged at the bottom with yellow trimming and green and blue jewel pieces, yellow petal-like sleeve cuffs, a yellow collar, a yellow bow with a green jewel piece at the center, white fingerless gloves with yellow trimmings, golden bracelets, white shorts with yellow trimming, light yellow shoes with yellow soles, and yellow anklets with petals attached. Additionally, Miku's twin-tails are held with yellow petals with portion of each of them held in a donut shape.", "[\"Beware of the Miku Miku Germs♪\",\"So Much Loving You★\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3505, "Farewell", "Farewell", "ryono", "/miku_monday/Farewell.png", "The Module's attire consists of a white collared shirt with light yellow flower designs, a blue bird design on the left chest, and buttons reminiscent of the phases of the moon, a black skirt with grey flower designs and a small extra layer, matching stockings, red Mary-Jane pumps, and yellow flower hairpins that hold Miku's twin pigtails.  In Project DIVA Arcade Future Tone, its PlayStation 4 port, and MegaMix, her bangs become shorter, and also her pigtails become thinner.", "[\"Kimi no Taion\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3130, "Fei-Yen Style", "Fei-Yen Style", "Katoki Hajime", "/miku_monday/Fei-Yen Style.png", "Miku's Module is based off the character SRV-14-A Fei-Yen from Cyber Troopers Virtual-On: Operation Moongate. It consists of a more robotic version of Hatsune Miku's default outfit, which includes a turquoise and grey helmet with light blue visors, a metallic-tiled shirt the turquoise trimmings, a more bulky skirt with turquoise flaps, grey flappers connected to the back of the skirt, grey robotic gloves, and a battery pack with a CD running on it.", "[\"Melody...\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4038, "Final Fusion", "Final Fusion", "Nagimiso", "/miku_monday/Final Fusion.jpg", "The Module's attire consists of a white coat with grey stripes on the sides, a gold zipper and teeth, red puffy sleeves and gloves, hexagonal patterns on the bottom, and a gold bug-like contraption with green lights on the back. There is also a large, light-green skirt with white hexagonal patterns, and red leggings and boots. Additionally, Miku's hair becomes teal, her bangs are horizontally cut, her twintails are horizontally cut on their bottoms and are of varying lengths, and she wears a light-red helment with white pentagonal patterns and has gold coverings that cover the ears chin and the back of the head and include extended antennas.  This alternate version of Chopstick has the helmet cover three-quarters of Miku's face, leaving the mouth exposed, and has four greenish-white wings sprouting from the contraption on the back. When observed at certain angles, Miku is wearing a black mask.", "[\"Babylon\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3196, "FOnewearl Style", "FOnewearl Style", "SEGA", "/miku_monday/FOnewearl Style.png", "Miku's Module is based off the Force-type outfit worn by female Newmans from the game Phantasy Star Online 2.", "[\"The MMORPG Addict's Anthem\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7483, "Furimawasareta Negi", "Furimawasareta Negi", null, "/miku_monday/Furimawasareta Negi.png", "The Module consists simply of a green recolor of Miku's default outfit, including white shirt with green hues, white detachable sleeves with green hems, white and green, futuristic hairbands, a green necktie, a light-green skirt, green stockings, and yellow shoes.  Additionally, Miku wields a spring onion in her right hand.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3021, "Galaxy", "Galaxy", "119", "/miku_monday/Galaxy.png", "The Module's attire consists of greyish-blue headphones with white trimmings, an attached mic with two turquoise rectangles, and an orchid square on the ear-pads, a white sleeveless jacket with orchid trimming and speaker-like ornaments on the sides, matching detachable sleeves, a white crop top with violet trimming, an orchid skirt, long white socks, boots with orchid soles, and thin translucent dishes on Miku's twin tails.", "[\"Last Night, Good Night\",\"Nightmare ☆ Party Night\",\"SYMPHONIC DIVE\",\"Quartet of Multiple Futures -Quartet Theme-\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2989, "Gallia Squad 7", "Gallia Squad 7", null, "/miku_monday/Gallia Squad 7.png", "Miku's Module is based off of Alicia Melchiott from Valkyria Chronicles. It consists of the standard militia apparel for female members of the Gallian Militia, complete with Alicia's iconic red bandana.", "[\"A Song of Wastelands, Forests, and Magic\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3508, "GHOST", null, "HASSAN", "/miku_monday/GHOST.png", "The Module's attire consists of a black one-piece sleeveless dress with a small diamond opening on the chest area and a larger opening on the back, a frilled collar with a small black ribbon, and a small teal stripe going around the hem. There are also black long gloves and thigh-high boots with teal stripes going down the center and teal soles. Additionally, Miku's skin becomes pale white with a crack on the right side of her face, her eyes become blue with purple hues, her hair becomes purple with blue hues with messy bangs, and her twin-tails become more curled and wild with various strands sticking out that are held with purple strings.", "[\"Ghost Rule\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2866, "Gothic", "Gothic", "KARASU-R", "/miku_monday/Gothic.png", "The Module's attire consists of black circular headphones with light turquoise trimmings and an attached mic becoming thick at the end, a white collared shirt, a thin dark grey bowtie, an overall skirt with a white two-eighth music note stitched on the bottom-left side, a black ribbon around the waist, and white frills, matching detachable sleeves, black stockings with ribbons on the side of the thighs, dark grey Mary Janes shoes, and ribbons holding Miku's twin-tails.", "[\"Jaded\",\"Disruptive Diva\",\"VOiCE\",\"Paris Cinema Girl\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3246, "Gradation Resort", "Gradation Resort", "[[SEGA]]", "/miku_monday/Gradation Resort.png", "The Module's attire consists of a two-tone bikini featuring shades of teal and turquoise, a white frill and teal bow on the top, two bows on the sides of the bottom, and teal crocs. Additionally, Miku's twin-tails are held with turquoise scrunchies, and her left bangs have matching musical note hairpieces.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4039, "Green Tanuki", "Green Tanuki", "saine", "/miku_monday/Green Tanuki.jpg", "The Module's attire consists of a black mostly unzipped sweater with white fluffy rims and black tanuki ears with teal heart-shaped canals on the hoodie, teal stripes on the sleeves, a heart on the left side, cuffs with a white stripe, and a tanuki head on the back, black shorts with a teal stripe on the hem, a teal bodysuit with a black collar, a black and teal striped necktie, and short black boots with folded cuffs and teal stripes and heels. Additionally, Miku's hair gains teal hues towards the bottom and her twin-tails become wavier, are placed under her head, and are tied with black and teal bows.", "[\"Even a Kunoichi Needs Love\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3023, "Ha2ne Miku", "Ha2ne Miku", null, "/miku_monday/Ha2ne Miku.png", "The Module's attire resembles that of Hatsune Miku's default outfit. The difference is her necktie is shorter, she has a white short-sleeved undershirt in place of detachable sleeves, there are no parameters on her skirt, her boots are replaced with long black socks with black loafers, and her headphones have no attached mic.", "[\"The secret garden\",\"Sayonara, Goodbye\",\"High School Days\",\"39\",\"Innocence\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3268, "Hana-Kotoba", "Hana-Kotoba", "72", "/miku_monday/Hana-Kotoba.png", "The Module's attire consists of a standard Japanese school uniform: including a white shirt with a navy-blue collar and cuffs, a moderate amaranth ascot tied with a white hair tie, a knee-length navy-blue skirt, white socks, and brown loafers. Additionally, Miku's skin becomes pale, her hair, eyebrows, and irises become brownish black, and her pigtails are placed lower to her head and resting on her shoulders reaching to the upper part of her skirt. She never wears nail polish.  In the Arcade Future Tone series and MegaMix, the loafers become a dark shade, and with MegaMix having her hair and facial looks become a very dark brown.", "[\"Pinky Swear\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 6874, "Harukaze", "Harukaze", "Yuichirou Kojima", "/miku_monday/Harukaze.png", "The Module's attire consists of black headphones with the bottom earpads being golden brown, a pink and red jacket with a pale-yellow stripe going across the center and flannel lower sleeves. There is also a white, collared shirt with pink frills on the collar and a red stripe going down the shirt that connects to the red stripe on the hem, a gold and white striped tank top, blue jeans, red shoes with a pink stripe and black soles, and pink squared hairbands. Additionally, Miku's twin pigtails are shortened to the length of her arms, and her bangs are combed to the left.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3027, "Hatsune Miku Append", "Hatsune Miku Append", null, "/miku_monday/Hatsune Miku Append.png", "Miku's Module is based off the illustration featured on the package of the \"Hatsune Miku Append\" voicebank. It consists of a white turtleneck tank-top that extends down to the upper thighs, matching accents with turquoise hues, black finger loop gloves that cover the middle fingers, a specially designed black belt with speaker-like ornaments and red and turquoise lightings, black stockings with diagonal openings and turquoise rectangles, a silver anklet on the left leg, and black speaker-like hairbands with red lightings. Additionally, her hair, eyes and nails become a lighter turquoise and her twin-tails become thinner and split-ended.  In Project DIVA 2nd and Extend, her eyes are turquoise.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3037, "Hatsune Miku Butterfly", "Hatsune Miku Butterfly", "OHSE", "/miku_monday/Hatsune Miku Butterfly.png", "The Module's attire consists of a dark greyish cyan and dark teal jacket with turquoise and light brilliant orange trimmings and matching small butterfly designs, a pink obi sash with a light brilliant orange dragon design tied around Miku's waist, a dark greyish aquamarine petal-like and mint green wrapped frilled skirt, long dark socks with black cuffs, black shoes with dark and light teal cuffs and dark golden soles with a teal stripe running through each sole, and hairbands that match her jacket with light brilliant fuchsia flaps featuring black butterfly designs sticking to them, as well as a corsage of sakura flowers on the left side of her hair and a red tattoo codenamed \"01 VOCALOID\" on the left side of her chest.   In Project DIVA 2nd and Extend, the soles become a lighter shade, alongside F 2nd and X, the dark greyish cyan part of the jacket darkens, the trimmings and designs become gold, and the flaps - moderate orchid in the F games - rest on the back of her twin tails.", "[\"Magnet\",\"Jugemu Sequencer\",\"NekoMimi Archive\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3039, "Hatsune Miku Christmas", "Hatsune Miku Christmas", "SEGA", "/miku_monday/Hatsune Miku Christmas.png", "The Module has two alternate versions that share certain differences.  In Hatsune Miku: Project DIVA 2nd, Extend, Live Stage Producer, Mirai 2 and Mirai DX, F 2nd, and X, it consists of a Santa hat with special openings on the sides where Miku's twin-tails poke out of, puffy white headphones, a red Santa dress with white pockets, as well as a matching cape with a puffy collar and a gold star as a centerpiece, a white tie with two red stripes resembling her default one, red gloves with puffy cuffs, matching high-heeled boots with puffballs hanging off the cuffs, and a black and turquoise ribbon tied to her left thigh.  In Hatsune Miku: Project DIVA Arcade, Dreamy Theater 2nd and Extend, Arcade Future Tone and its PlayStation 4 port, and MegaMix, the hat has a black and turquoise ribbon attached to it, puffballs hanging off the star, red gloves having the same ribbons, black high-heeled boots, and her hair is worn loose.", "[\"Requiem for the Phantasma\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3063, "Hatsune Miku Cute", "Hatsune Miku Cute", "eb", "/miku_monday/Hatsune Miku Cute.png", "The Module's attire consists of a short white coat with a light blue lace and lighter green trimming that is held by a white ribbon, a lavender and white crop top, ribbons on the left wrist and right arm, a black speaker band on the right wrist, black arm bands with turquoise trimming, a ribbon necklace with a silver plate, lavender shorts, white leggings with lavender trimming, black anklets with white speakers, white slip-on heels with yellow soles, black circular mic-attached headphones with a light-green illumination and screens on the ear-pads that feature turquoise digital hearts that light up, and white ribbon bows on Miku's twin-tails.", "[\"Promise\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3402, "Hatsune Miku Emerald", "Hatsune Miku Emerald", "bob", "/miku_monday/Hatsune Miku Emerald.png", "The Module's attire consists of black headphones, a stylized teal cheongsam with various emerald and jade hues, dark blue designs with dark yellow decorations, and small red pinks, matching detachable sleeves held with red strings, dark stockings with laced stockings, and black high-heels with strings. Additionally, Miku's twin-tails become thin and are held with specially designed red hairbands.", "[\"World's End Dance Hall\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4731, "Hatsune Miku Haruka Style", "Hatsune Miku Haruka Style", null, "/miku_monday/Hatsune Miku Haruka Style.jpg", "The Module's attire is based off the \"Primary-Star Plum\" costume from the video game THE IDOLM@STER SP of the synonymous franchise, specifically the one worn by character Haruka Amami. It consists of a pink one-piece dress with the front section being short just below the waist in a double-V cut and the back section going down to the upper-thigh. The dress includes white star designs, puffy, white edge trimmings, and a light-blue waistband with ribbons on both sides. There is also a gold-yellow choker, white gloves with petal shaped openings, a white skirt, and pink boots with puffy, white cuffs. Additionally, Miku's twin-tails are held with twin pink ribbons with pink frills. The ribbons, presumably, are a reference to Haruka's trademark twin ribbons.", "[\"GO MY WAY!!\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3132, "Hatsune Miku Mousou Girl", "Hatsune Miku Mousou Girl", "Tama", "/miku_monday/Hatsune Miku Mousou Girl.png", "The Module's attire consists of a brown school blazer with six black buttons, a white collared shirt, a red bowtie, an olive green skirt, black stockings, and dark brown loafers.", "[\"Mousou Sketch\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3150, "Hatsune Miku Polka Dot Bikini", "Hatsune Miku Polka Dot Bikini", null, "/miku_monday/Hatsune Miku Polka Dot Bikini.png", "The Module's attire consists of a white frilled, two-piece bikini with multi-colored polka dots, a small bow on the center of the top and a large bow hanging on the left side of the bottom's waistband. Additionally, Miku's twin-tails shorten to waist-length and are held with hair scrunchies that match her bikini.", "[\"Summer Idol\",\"Sekiranun Graffiti\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3148, "Hatsune Miku Racing Swimsuit", "Hatsune Miku Racing Swimsuit", null, "/miku_monday/Hatsune Miku Racing Swimsuit.png", "The Module's attire consists of a simple navy blue one-piece swimsuit for females with thin white shoulder straps and a gold tag on the bottom left side. Additionally, Miku's hair is styled in a braided ponytail.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2828, "Hatsune Miku Swimwear", "Hatsune Miku Swimwear", null, "/miku_monday/Hatsune Miku Swimwear.png", "The Module's attire consists of a two-piece swimsuit with white and turquoise stripes and a yellow triangular tag on the left side of the bra.  In Hatsune Miku: Project DIVA F 2nd and X, Miku's headphones were removed, while in the rest of the games, her toenail polish is removed.", "[\"Dear cocoa girls\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3069, "Hatsune Miku Swimwear B", "Hatsune Miku Swimwear B", null, "/miku_monday/Hatsune Miku Swimwear B.png", "The Module's attire consists of a blue two-piece bikini with light blue frills and a scrunchie on Miku's left wrist. Additionally, Miku's hair is held in a high ponytail with a blue hair scrunchie.", "[\"Magical Sound Shower\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3025, "Hatsune Miku Swimwear S", "Hatsune Miku Swimwear S", null, "/miku_monday/Hatsune Miku Swimwear S.png", "The Module's attire consists of a simple navy blue school swimsuit for females with a gold tag on the bottom left side.", "[\"I Really Do Understand\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3691, "Hatsune Miku Swimwear Tan", "Hatsune Miku Swimwear Tan", null, "/miku_monday/Hatsune Miku Swimwear Tan.png", "The Module's attire consists of a two-piece swimsuit with white and turquoise stripes and a yellow triangular tag on the left side of the bra.  This alternate version of Hatsune Miku Swimwear has Miku's skin gain a bronze tan. In Arcade Future Tone and MegaMix, Miku's headphones were included.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3198, "Hatsune Miku V3", "Hatsune Miku V3", "iXima", "/miku_monday/Hatsune Miku V3.png", "The Module is based on the illustration featured on the package of the \"Hatsune Miku V3\" voicebank. It is similar in appearance to Miku's default attire. The differences, however, include the colors becoming more bright-colored, the tag on her shirt becomes silver, her detachable sleeves are see-through and feature more parameters, her skirt also having more parameters with the belt chain having a white line included in the pattern, her loafers are much more noticeable with the tips becoming slightly pointed, and her headphones become black and circular with the earpads codenamed \"V3 VOICE ROM\" in black except the \"3\" written in turquoise on a matching striped background and \"CARTRIDGE\" in light-yellow, and having a silver bowl-with-stick design with the middle including a red light moving side to side, and two buttons, and the tip of the attached mic becoming green and oval-shaped. Additionally, Miku's twin-tails become wavier, with the strands becoming more separated towards the ends.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3154, "Hatsune Miku Yukata Style", "Hatsune Miku Yukata Style", "misa", "/miku_monday/Hatsune Miku Yukata Style.png", "The Module's attire consists of a dark blue yukata with various design patterns of chrysanthemum, butterflies, and musical notes, held with a turquoise and green obi sash, and black sandals with teal straps and orange soles. Additionally, Miku's hair is styled in twin buns held with scrunchies that appear similar to the floating hairbands from her default outfit.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7575, "Hatsune Miku: Halloween", "Hatsune Miku: Halloween", "Suoh", "/miku_monday/Hatsune Miku: Halloween.jpg", "The Outfit's attire consists of a black strapless bottom V-cut dress with white frills on the hems, an orange bow with a gold ornament, black detachable sleeves with puffed white openings, a gold bracelet on the left wrist, bat wings, an orange overskirt with two jack-o'-lantern-esque smiles and the center having translucent fabric held by a brownish-gold skirt piece, a white skirt layer, brownish-gold and white orbs adorning the ends of the orange skirt, a white bow on the back, black and white striped boots with bat wings on the back and yellow eyes on the toes, orange and white bows, and white large earrings. Additionally, Miku wears orange eyeliner and her twin-tails gain a blue hue and become wavy towards the bottom, reminiscent of ghosts.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2861, "Heart Hunter", "Heart Hunter", "Takumi Torigoe", "/miku_monday/Heart Hunter.png", "The Module's attire consists of grey headphones with an attached mic on the right ear-pad and light ear-pads and rectangles on the handle, red ribbons, a reddish-pink dress that exposes the navel and sides, a dark purple collar connected to the top of the dress to form a heart, reddish-pink fingerless gloves with glowing hearts and dark purple trimmings, a matching frilled skirt held by a red belt with a yellow heart-shaped buckle, dark purple leggings with reddish-pink trimmings, an open heart on each side, and down arrows that extend down to dark pink shoes, and bat wings and a devil tail. Additionally, Miku's hair is in short pigtails with the rest of it braided in the back, and her nails become pink.  In the PSP titles, the heart-shaped buckle is slightly different, it is a dark yellow as shown in Dreamy Theater, the Arcade and Future Tone series, and MegaMix, and in F 2nd and X, the shoes become high-heels.", "[\"The World is Mine\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3204, "Heartbeat", "Heartbeat", null, "/miku_monday/Heartbeat.png", "The Module's attire consists of grey headphones with magenta covers, a black bow with small white stripes and holes in which the twin tails go through, a grey turtleneck jacket with darker grey areas, a light orange center attached with a grey power button with a pink light glowing in the center and a mouse at the back, the bottom sleeves becoming slightly enlarged and include light orange speakers and small black dials, and attached fingerless gloves, a black skirt with a grey stripe and additional frills, and grey thigh-high heeled-boots with light orange trimmings and black soles.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3119, "Hello World.", null, "[[sasakure.UK]]", "/miku_monday/Hello World..png", "The Module's attire consists of a white dress with black, aqua green, light arctic blue, and bright pink systematic features, a matching earpiece with a strong red button on the left ear, black stocking boots, a floating light arctic blue bracelet on the right wrist, and an incomplete halo floating around the head. Additionally, Miku's hair is worn loose, her nose bang has an eye-length section, and her eyes become a moderate aquamarine.", "[\"*Hello, Planet.\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3184, "Hello, Good Night.", null, "sasakure.UK", "/miku_monday/Hello, Good Night..png", "The Module's attire consists of an antenna on the head with arrows pointing left and right, a long white and grey nightgown with a multicolored stripe zagged across, a blue stripe zagging across the right sleeve, black and white circles that resembles the phases of the moon, and blue trimming on the bottom, a necklace with a large key featuring a crescent moon connected on, and a silver anklet. Additionally, Miku's twin-tails have jigsaw puzzle cubes with white, blue and orange pieces over them.", "[\"Negaposi*Continues\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 6800, "Hello/How are you? (Outfit)", "Hello/How are you?", "Mizutamako", "/miku_monday/Hello/How are you? (Outfit).jpg", "The Outfit's attire consists of a lightest green shirt with an opening in the middle that exposes a white plaid, buttoned shirt with a frilled collar and a blue ribbon tied on. There are also green plaid shorts held with matching suspenders with gold buckles and burnt sienna boots. Additionally, Miku has her hair held up in a top bun.", "[\"Hello/How are you?\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4042, "High Fever", "High Fever", "[[PinocchioP]]", "/miku_monday/High Fever.jpg", "The Module's attire consists of a pink, long-sleeved shirt hanging off the shoulders with white hems and arrow patterns, a salmon skirt, and white loose socks. Additionally, Miku's hair becomes light blue and rather messy, her twin-tails reach her hips and are held with hairbands in the shape of red and white capsule pills, her eyes become pink, and there is a pink arrow tattoo pointing upward under her left eye.", "[\"Slow Motion\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7519, "Honey Bear", "Honey Bear", null, "/miku_monday/Honey Bear.png", "The Module consists of an orange, bear onesie with the hoodie having beaded eyes, a white muzzle, yellow ears with a black and red striped bow on left ear, and holes on the sides of Miku's twintails. The onesie also has a yellow mid-section with an orange front-pocket, a golden bell on the chest, claws on the sleeves, and a honey jar-like backpack with blue straps.  Miku also holds golden bells with black and red, striped ribbons on the handles.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3206, "Honey Whip", "Honey Whip", "saitom", "/miku_monday/Honey Whip.png", "The Module's attire consists of a black long-sleeved crop top with a pink collar, cuffs, and trimmings, a gold crest with the kanji  on the left collar, gold buttons and cufflinks, a black frilled bra, a multilayered black and pink skirt, a pink and black belt with a gold buckle, black stockings with garters, and black boots with pink cuffs, straps, and heels. Additionally, Miku's hair and eyes become light turquoise, her twin-tails shorten and are held with black and pink butterfly hairclips, and her nails become pink.", "[\"Sweet Devil\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3221, "Ichi-no-Sakura Blossom", "Ichi-no-Sakura Blossom", "Ittomaru", "/miku_monday/Ichi-no-Sakura Blossom.png", "The Module's attire consists of a mauve military-styled jacket with dark epaulets, gold chains, a Sakura-styled medallion, pink Sakura designs on the right sleeve flap, and a large  kanji printed on the back, a matching peaked cap with a Sakura design on the rim, brown wristbands and half gloves, a mauve pleated skirt, light-mauve stockings, and brown geta boots. Additionally, Miku's skin becomes a lighter shade, her hair becomes dark green, her eyes become dark brown, she wears red eyeliner, and her twin-tails become thinner.  In Project Mirai 2 and Project Mirai DX, the Module's color becomes a lighter-mauve, the boots become shoes, and the half-gloves become fingerless gloves.", "[\"Senbonzakura\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3223, "Ichi-no-Sakura White Blossom", "Ichi-no-Sakura White Blossom", "Ittomaru", "/miku_monday/Ichi-no-Sakura White Blossom.png", "The Module's attire consists of a military-styled jacket with dark epaulets, and silver chains, a matching peaked cap, brown wristbands and half gloves, a pleated skirt, stockings, and geta boots. Additionally, Miku's skin becomes a lighter shade, her hair becomes dark green, her eyes become brown, she wears red eyeliner, and her twin-tails become more thinner.  This alternate version of Ichi-no-Sakura Blossom recolors all instances of mauve and brown to white, all Sakura petal designs are replaced with Japan's rising sun symbol, and her stockings becomes black.", "[\"Senbonzakura\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3084, "Infinity", null, "[[cosMo@BousouP]]", "/miku_monday/Infinity.png", "The Module's attire consists of a black dress; a black collared vest with white frills and a black bow on the back, a matching necktie with a white leek printed on it, detachable sleeves with white frills, black socks with white frills, black Mary-Janes with matching flowers on the toes, cog-like mic-attached headphones, and black hairbands with black flowers on them. Additionally, Miku's skin becomes pure white, her hair becomes a light blue with violet hues on top and her twin-tails spiral at the bottom, her eyes become red, and her nails are painted violet to match the hues.  In Dreamy Theater and the Arcade and Future Tone series, her skin is a whitish indigo.", "[\"The Intense Voice of Hatsune Miku\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3186, "Innocent", "Innocent", "Moka Ichiyo", "/miku_monday/Innocent.png", "The Module's attire consists of a black dress with its shoulder straps tied in a bow at the back, as well as purple frills and white stitching, matching short detachable sleeves, a pale orchid bow resembling a butterfly on the back of the dress, a silver ring on the right hand, black high-heels with purple butterfly attachments on the straps, and large purple butterfly-like hair bands. Additionally, Miku's twin tails become shorten and thicken with two short strands on top and split ends, and her nose bang is pointed downward and has two strands.", "[\"ACUTE\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3210, "Interviewer Miku", "Interviewer Miku", "saine", "/miku_monday/Interviewer Miku.png", "The Module's attire consists of a long white hoodie-sweater with hot pink strings, a zipper, teeth, and a hot pink and grey heart at the back, a black undershirt with matching shorts, and black and hot pink satin bows. Additionally, Miku's hair becomes teal, her twin-tails become wavy and are placed downward, her bangs are parted to the left, and her eyes become hot pink.", "[\"Interviewer\",\"Gizmo\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4053, "Ivy Rabbit", "Ivy Rabbit", "Rella", "/miku_monday/Ivy Rabbit.jpg", "This module's attire consists of a white sleeveless dress with a black and white checkered bow that hangs from Miku's left shoulder and connects to the dress. The bottom of it is decorated with a row of a variety of playing cards. There are also white gloves, the four pips that are tattooed on each leg with a line on the bottoms that lead downwards, white high-heels, and a black large top hat with white rabbit ears sticking out of the sides. Additionally, her hair becomes whitish-green and her eyes red, resembling the rabbit.", "[\"Quirky Medley - Giga-Remix\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3072, "Jersey", "Jersey", "hekopon", "/miku_monday/Jersey.png", "The Module's attire consists of a short, white turtleneck jersey with a yellow collar, cuffs, and hemline, a light orchid zipper with green teeth, and light green sleeves with yellow stars, a light green skirt with yellow trimmings and green laces, turquoise socks with yellow stripes, yellow shoes with white puffed toes and light green soles with a light orchid star on each sole, and yellow headphones with light green stars and a handle. Additionally, Miku wears her hair in a bun with the ends in hair tie form.", "[\"Po Pi Po\",\"Gigantic Girl\",\"Beware of the Miku Miku Germs♪\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4046, "Judgment", "Judgment", "Tama", "/miku_monday/Judgment.jpg", "This Module consists of a black judicial hat, a long black judicial robe that reaches a little below the knees, a white dress shirt with a dark maroon bow, black thigh-high stockings with white rings on the ankles, and black shoes. Additionally, Miku's hair and eyes become dark turquoise, her twin-tails become shorter that reaches her chest with black hair ties, and her bangs are put off to the side.", "[\"Love Trial\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3270, "Kasha", "Kasha", "72", "/miku_monday/Kasha.png", "The Module's attire consists of a black coat with extended flaps on the sleeves with sprout designs, the left sleeve being rolled up and has a matching bow on the shoulder, a hakama shirt with a shortened skirt held with a small sash, leggings, and high-heels with ankle straps. The headwear includes brilliant amaranth and black ribbons and a corsage of vanilla flowers on the left side and two of them at the back on the right. Additionally, Miku's hair becomes a pale, light greyish opal, her twin-tails reach to her thighs and are placed unsteadily; with the right pigtail in the middle and the left one high and braided into a band, her bangs become symmetrical, and has two strands with the left one resting on her shoulder.", "[\"Pinky Swear\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3194, "Kitty Cape", "Kitty Cape", "Milo", "/miku_monday/Kitty Cape.png", "The Module's attire consists of brown cat-eared headphones with yellow buttons for the earpads and pink canals on the ears, a yellow dress, a fluffy tan cape held with a small red ribbon and including yellow buttons, red gloves, a red waist belt with a big yellow button-styled pouch attached, tan socks, and red boots.", "[\"Nyanyanyanyanyanyanya!\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2850, "Kitty Cat", "Kitty Cat", "Pontaro", "/miku_monday/Kitty Cat.png", "The Module's attire consists of an ashen grey collared shirt with a short red tie, a choker with a gold bell on it, black pants with brown suspenders and a belt with two pink paws and a grayish-violet fish, pale, light grayish olive cat designs on the knees, a black tail attached to the pants, paw-like shoes, black cat earmuffs, and large paw-like gloves on the hands. Additionally, Miku's twin tails become shortened, which surpass her waistline.", "[\"Rain With A Chance of Sweet*Drops\",\"NekoMimi Switch\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7552, "KONEKO NO PAYAPAYA (Outfit)/Miku", "KONEKO NO PAYAPAYA", "Onecup P", "/miku_monday/KONEKO NO PAYAPAYA (Outfit)/Miku.jpg", "The Outfit's attire consists of a pink string dress with ruffles on the top and matching detachable sleeves, blue, white, pink, and salmon stripes, pink and yellow orbs adorning the bottom hem of the dress, a black waist belt with a white cat with mismatching blue and green eyes as the buckle, a pink cat tail on the back of the dress, and pink high-heels. Additionally, Miku's twin-tails are held with pink head wraps.", "[\"KONEKO NO PAYAPAYA\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3192, "Lab Girl", "Lab Girl", "Kuchibashi P", "/miku_monday/Lab Girl.png", "The Module's attire consists of a white collared lab coat with moderate red, moderate blue, and greyish emerald green square designs on the bottom right side and a chain attached to a small slit, a greyish blue shirt, a moderate scarlet bowtie, a greyish persian blue skirt, very dark blue socks, and brown loafers. Additionally, Miku's hair becomes moderate azure, her eyes become a greyish persian blue, and her nail polish is removed.", "[\"What Do You Mean!?\",\"Kimi Ni\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4032, "Layered Envy", "Layered Envy", "SHIN-ICHI SATAKE", "/miku_monday/Layered Envy.jpg", "The Module's attire consists of a black layered dress with dark blue inner fabric and a ribbon, matching gloves and boots with dark blue cuffs, trimmings and soles, and large dark blue ribbons to hold Miku's twin-tails. Additionally, her hair becomes a pale blue with her twin-tails reaching her upper thighs, having a pointed-shape at the end and a thin portion reaching her upper thighs, and her eyes become dark blue. Overall, the Module is black and dark blue with the exception of her hair color.", "[\"Solitary Envy\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3445, "Liar", "Liar", "gorou_", "/miku_monday/Liar.png", "The Module's attire consists of a warm gray blazer, a white collared shirt, a mint green and brown striped necktie, a dark skirt, matching long socks with brown stripes, and brown loafers. Additionally, Miku's hair and eyebrows become a dark grayish blue with the hair becoming waist-lengthened and tied in low pigtails with red hair ties, and her irises are gray. In Project DIVA Arcade Future Tone, its PlayStation 4 port, and MegaMix, her nose-bangs and right fringe become thick and pointed to the right.", "[\"Doubleganger\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3166, "Linkage", "Linkage", "redjuice", "/miku_monday/Linkage.png", "The Module's attire consists of a white bodysuit that goes down to the upper thighs with a black center featuring light blue, green, red, and yellow lights on the corners, silver plates with orange attachments connected on a belt in the back, and long boots that match the suit. Additionally, Miku's headphones and plates attached to her hairbands also match the hip plates, her hair, eyebrows, eyes, and nails become sea green, her twin-tails reach to her thighs and have short split ends, her bangs have two short ends between her nose bang, and has a cowlick hanging out.", "[\"Tell Your World\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3059, "Little Red", "Little Red", "Tda", "/miku_monday/Little Red.png", "The Module's attire consists of a red dress with puffed sleeves, white frills, yellow stitching, and a red bow on the back, a red hoodie with white jagged trimming, a red bow, and a wolf decoration on the top, a white apron with red bows and flower designs, long white socks with yellow ribbons tied on the top, red high-heels with yellow bows, and a red wristband on the right wrist.", "[\"Clover♣Club\",\"Oha-Yo-del!!\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4031, "Lollipop", "Lollipop", "honyalala", "/miku_monday/Lollipop.jpg", "The Module's attire consists of a light-pink dress shirt with bows on the bottom sides and on the top center, puffed shoulders, pink cuffs with frills, and a pink schoolgirl collar and undershirt with white edge trimmings, white and pink frilled shorts, light-pink bands on Miku's thighs, a band-aid on her left knee, differing sized white frilled sock with light-pink cuffs, a short sock on the left leg, and a long sock on the right leg, pink platform shoes with folded cuffs and white frills, white and brown centers with pink bows, and light-pink soles, a black choker with a pink donut charm, pink frilled hairbands with the left one having a two-strawberry and kiwi accessory, and a strawberry ring on her right index finger. There is also a dark pink rabbit wearing a big purple bow tie and boots on her back with lighter-pink straps over her shoulders that can help her carry. Additionally, her hair becomes mint green and more thicker, and her eyes become lime green.", "[\"LOL -lots of laugh-\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3172, "Magical Mirai", "Magical Mirai", "CHRIS", "/miku_monday/Magical Mirai.png", "The Module is based off the outfit worn by Miku in the key visual for \"Hatsune Miku Magical Mirai 2013\". It consists of a dark-blue tailcoat with puffed shoulders and white cuffs, a blue frilled dress with white hems and a light-blue bow tied at the waist, white gloves, matching knee-high boots with purple bows and dark-blue toes, a large dark-blue top hat with a white center stripe that has a card with a spade on it tucked in, as well as a gold star ornament dangling off the left side, and purple hairbands. Additionally, her front bangs become thickened and side-swept and the bottom half of her twin tails becomes a light color.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2837, "Magician", "Magician", "Kenji Hirabaru", "/miku_monday/Magician.png", "The Module's attire consists of a black blazer, a frilled white dress-shirt and a black bow tie with a light teal jewel in the middle, legless black shorts, fishnet leggings, thigh-high black boots, white gloves, a black hat with a red stripe, circular headphones with fuchsia trimmings, and a black and red satin bow. Additionally, Miku's hair is worn in a low ponytail.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7489, "Maracas", "Maracas", null, "/miku_monday/Maracas.png", "The Module consists simply of a pair of maracas with dark-teal heads that have magenta stripes and teal triangle designs.  Miku's Vintage Dress is used as a base for this.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3488, "March Hare", "March Hare", "honyalala", "/miku_monday/March Hare.png", "The Module's attire consists of a dark pink rabbit hood with two blue bows on the rabbit's right ear, and a big dark pink bowtie with white frills on the bottom center, a light orange shirt with puffed sleeves, a dark pink and light orange frilled vest with blue stripes, pink gloves with round cuffs, a frilled dark blue skirt, a dark pink rabbit tail, long light orange socks with dark pink filled cuffs, and platformed purple boots with a dark pink center, laces, soles, and heels. Additionally, Miku's hair and eyes become a pale light grayish cyan, tied in thin pigtails that surpass her hips, and her bangs become slightly symmetrical.", "[\"LOL -lots of laugh-\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3265, "Marionette", "Marionette", "Yamako", "/miku_monday/Marionette.png", "The Module's attire consists of a cobalt blue vest with a pink striped bow, a white shirt with yellow sleeves with white polka dots, black gloves, scarlet striped overalls with puffed legs and light green polka-dotted and yellow striped patches on the left leg and three light yellow buttons on the center, dark greyish amaranth shoes with pointy tips, light yellow balls on the toes, and white soles, a black felt hat with blue and red stripes on the center, and red hair ties. Additionally, Miku's hair becomes a pale turquoise, her twin tails become shorter and more spaced out, her bangs surpass her eyebrows with the long bang extending towards her eyes, and she has three hot pink dots and a cobalt blue tear painted under her right eye.  In Project DIVA F 2nd and X, the dots have a red hue.  The alternate version has Miku wearing a white clown mask. Beginning with Project DIVA Arcade Future Tone, it becomes the main version.", "[\"Karakuri Pierrot\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 6802, "Matryoshka (Outfit)/Miku", "Matryoshka", "Hachi", "/miku_monday/Matryoshka (Outfit)/Miku.jpg", "The Outfit's attire consists of a green jersey with light-green stripes on the sleeves, as well as light-green on the the trims and pockets. There are also brown gloves, black shorts, black and white striped stockings, and black boots. Additionally, Miku wears wired black headphones with white earpads, with the wire going into the left pocket.", "[\"Matryoshka\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2983, "Meiko Style", "Meiko Style", null, "/miku_monday/Meiko Style.png", "The Module attire is based off of MEIKO. It consists of a short red sleeveless jacket with black trimming, red fingerless gloves with black trimming and pink heart designs on the back sides, black frilled cuffs, a red skirt with black frills held by a teal belt, black shorts, a yellow bow tied to Miku's left leg, black frilled socks, and red boots with white and black trimming, yellow laces, and heart designs.", "[\"Dreaming Leaf\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3219, "Memoria", "Memoria", "Minakata Laboratory", "/miku_monday/Memoria.png", "The Module's attire consists of a pink coat with four brown buttons, white trimmings and small string tails attached, a navy blue dress with white frills, a red ribbon, white gloves, purple stockings, and brown boots. Additionally, Miku's hair becomes deep blue-gray and significantly shorter, tied in pigtails held with red ribbons resting on her shoulders.", "[\"World's End Umbrella\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3244, "Meteorite", "Meteorite", "SOE", "/miku_monday/Meteorite.png", "The Module's attire consists of a black, turtleneck dress with a white overpiece with flaps on the front and back, long sleeves that cover the arms, a brown collar, and a purple bow. There are also long, black boots with white bands on the upper thighs. Additionally, Miku's twintails are slightly thinner and has a yellow star piece placed on her left twintail.", "[\"Meteor\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3711, "MiCrystal☆", "MiCrystal☆", "mikoko", "/miku_monday/MiCrystal☆.png", "The Module's attire consists of a teal crop top with crystal-like frills and small teal neck straps, a white bow on the waist, a crystal skirt, teal gloves with petal-like cuffs, teal high heels with small straps, and crystal-like hairbands. Additionally, Miku's hair becomes diamond blue with rose quartz hues and white straps wrapping around her twin-tails.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2962, "Miko", "Miko", "paco", "/miku_monday/Miko.png", "The Module's attire is reminiscent to that of a shrine maiden. It consists of a white kosode with red trimming and a small red bow, matching detachable sleeves held by red threads, a red choker, a red skirt-length hakama held by a pink obi sash, white knee-length tabi socks with blue trimming and orange X-shaped stitching, and black sandals with red straps.", "[\"Song of Life\",\"Nightmare ☆ Party Night\",\"Dance of Many\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2972, "Miyabi", "Miyabi", "kurojishi", "/miku_monday/Miyabi.png", "The Module's attire consists of a pink kimono-esque shirt and matching skirt, a brilliant red obi sash with a white lining, pink detachable sleeves with white cuffs, lavender socks with flower designs and greyish violet cuffs with light points, sandals with greyish violet straps, and pink feather-like clips on Miku's bands, and her nails match the rest of the attire.", "[\"Sakura no Ame\",\"Nightmare ☆ Party Night\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3273, "Moonlight Butterfly", "Moonlight Butterfly", "Ebina", "/miku_monday/Moonlight Butterfly.png", "The Module's attire consists of a black bra with multicolored (malachite green, moderate orange, purple, and lighter yellow) designs on the hems that show a purple butterfly, a sleeve with gold designs on the right arm that doubles as a finger-loop glove, a red rim under the sleeve with the left side extending down to the chest area, a detachable sleeve with large white hems on the left arm, bandages that cover the upper torso, a red obi sash tied around the waist, black shorts that only cover the pelvic area, leggings, anklets with red rims, and high-heeled sandals. Additionally, Miku's hair becomes a dark green with lighter accents and pelvic-lengthened, and is tied in a ponytail with braiding on the top end, her irises and nails become light green, and she wears matching eyeshadow and black mascara. She also has hair pieces sticking out of her ponytail and bandages covering the left side of her face and her neck.  In F 2nd and X, her nails are the same color as her hair, her eyes and eyeshadow are a malachite green with the eye color becoming a strong shade and the eyeshadow a luminous vivid shade, and her mascara is absent.", "[\"Knife\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3714, "My Dear Bunny", "My Dear Bunny", "Hassan", "/miku_monday/My Dear Bunny.png", "Despite the Module's name, the design is more loosely based off the character Chuni Penguin from the arcade rhythm game \"CHUNITHM\". It consists of a black, one-piece, tuxedo-like dress with a yellow collar, yellow stripes on the hems, white frills under the fabric, a white pin with pink squares that resembles the arcade cabinet for \"maimai\", and a white rabbit tail on the back. There is also a white, sleeveless, collared shirt, a black bowtie, white cuffs with black buttons, dark pantyhose, and black high-heels with turquoise heels. Additionally, Miku's hair and eyes become a light-blue, her pupils gain a white twinkle, and she wears yellow headphones with attached yellow and orange rabbit ears that resemble Chuni's hairtuft.", "[\"Hand in Hand\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 6875, "Natsukaze", "Natsukaze", "Yuichirou Kojima", "/miku_monday/Natsukaze.png", "The Module's attire consists of grey headphones with pink hearts on the earpads, a black headband, a white shirt with a dull-yellow on the upper area and the short sleeves having white frilled openings, a black tank top, denim shorts held with black suspenders and six grey normal and two heart-shaped buckles, black tights, olive brown and white shoes, and yellow scrunchies. Additionally, Miku's twin pigtails become significantly short, reaching down to her neck with the end tips curving to opposite sides, and her bangs are combed to the left.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3031, "Natural", "Natural", "KEI", "/miku_monday/Natural.png", "The Module's attire consists of magenta headphones with Miku's serial code written in white on the ear-pads and a silver open handle, a white hoodie sweater with magenta trimming, a black shirt with punkish red trimming, a punkish red and black plaid skirt with a white frill and a matching belt chain, long striped thigh-high socks, magenta shoes with white laces and soles, and the accessories include magenta glasses and a black necklace with an apricot triangular-shaped figure-eight charm. Additionally, her eyes become a brilliant cerise.  In Project DIVA F 2nd, X, and VR Future Live, the sweater has strings and a dark pink zipper shown, her headphones have a black and magenta microphone attached on the right ear-pad, her glasses match the rest of her attire, her eyes become red, and the necklace's figure-eight charm becomes a metal squared-shape.", "[\"Gigantic Girl\",\"Look This Way, Baby\",\"So Much Loving You★\",\"Transparent Watercolors\",\"Lucid Dreaming\",\"1/6 -out of the gravity-\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 6593, "No Mask Underhanded Green", "No Mask Underhanded Green", "Tamotsu Shinohara", "/miku_monday/No Mask Underhanded Green.jpg", "The Module's attire consists of a green jumpsuit-like dress-shirt with white on the center and black with a gold hems on the chest area with the words  written in white and gold, a white neck covering, a green star-ornament embedded on the chest, a brown belt with a gold crest that reaches up to the chest, matching white gloves and boots with gold cuffs, white jumpsuit-pants, green stockings with gold hems, and a brown carrier on the right leg holding a shooting-type weapon.  This alternate version of Underhanded Green removes Miku's helmet, revealing her entire face.", "[\"Urotander, Underhanded Rangers\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7523, "Oiran Style", "Oiran Style", null, "/miku_monday/Oiran Style.png", "The Module consists of a purple uchikake kimono with red and yellow butterfly designs on the sleeve flaps, a crimson mana ita obi belt with orange flower designs, a long, green hakama with flower designs on the hems and red inner fabric, and long, black geta sandals with red straps. Additionally, Miku's hair is styled with a date hyogo hairstyle common with oirans with some hair also being braided, and sidetails extending past her shoulders, and wears a gold \"shiroko no sanmai gushi\" comb ornament and a multicolored flower ornament on the left side of her hair.  Miku also holds a shamisen in her left hand and holds the handle of a red and yellow foldable umbrella on her right shoulder.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3254, "Orange Blossom", "Orange Blossom", "Nidy-2D-", "/miku_monday/Orange Blossom.png", "The Module's attire consists of an orange cropped jacket with a small blue corsage on the right side, a white undershirt, an orange choker with a bow on the back, white armbands with petal-like bottoms held with small black bands with blue bows, black gloves with cuffs with blue lights and long white petal-like cuffs, an orange skirt with white stripes and frilled under-layers, a blue and white bow on the front and a bigger version on the back with an orange corsage, white stockings, small black boots with white cuffs, blue straps, and orange backs, a blue and white bow with a large orange speaker-like brooch on the left pigtail, and white hairbands. Additionally, Miku's hair becomes light blue, her twin pigtails are shortened, and her bangs have an extra fringe that surpasses her left eye.", "[\"DECORATOR\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3123, "Orbit", "Orbit", "refeia", "/miku_monday/Orbit.png", "The Module's attire consists of a lunar headpiece with long, white and purple flaps sticking out of it, a one-piece lavender dress with white frails reminiscent of a skirt with purple hues and long, blue ribbons held by a silver and blue jewel-piece and white boots with diagonal slits on the openings going in opposite directions. Additionally, Miku's twin-tails become thicker and gain blue and purple hues.", "[\"SPiCa\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3061, "Out and About", "Out and About", "DLEI", "/miku_monday/Out and About.png", "The Module's attire consists of a grey hoodie sweater with pockets, a pink system line design and can badges on the hood; a cerulean cube on the top left and a jolly roger on a black background in the middle and a little to the left, a light pink frilled skirt, long black socks with purple stars, white shoes with plaid orange designs, a pink can badge of a jolly roger on the front of the left shoe, black laces and soles, an orange necklace with a leek charm on it, showing an orange lined upside-down triangle, a light purple scrunchie and bracelets on Miku's right wrist, orange under-rim glasses, orange, black and grey squared headphones with leek designs around her neck, and black cubed hairbands holding her twin tails.  In Project DIVA F 2nd and X, the scrunchie becomes violet.", "[\"Aikotoba\",\"Sound\",\"The Two of Us - Futaride\",\"Catch the Wave\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3200, "Out of the Gravity", null, "Taro", "/miku_monday/Out of the Gravity.png", "The Module's attire consists of a black shirt with puffed sleeves and magenta frills, held with a long magenta bodice around the torso with thin black stitching, white wings on the back of the shirt, a black choker, a detachable cuff with lace on the left wrist, a multi-layered black and magenta box pleated skirt with the first black layer having one thick fuchsia stripe going around towards the near bottom edge, long black thigh-highs, dark grey knee boots that have bows on each outer side with fuchsia soles, and black bows with fuchsia stripes with the ribbon flaps extended on the left bow. Additionally, Miku's hair becomes shorter, thicker, and spiky towards the top with thinner parts extending down to the knees with additional strands spiralling around the twin-tails, and has a heart-shaped cowlick on the top of her head.  In Project DIVA Arcade Future Tone, its PlayStation 4 port and MegaMix, magenta ribbons are tied around her right wrist and hand, the detachable cuff has magenta dotted lines and a bow, her hair becomes teal, and her nails are painted magenta.", "[\"1/6 -out of the gravity-\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3707, "P4: Dancing All Night Miku", "P4: Dancing All Night Miku", "Shigenori Soejima (Atlus)", "/miku_monday/P4: Dancing All Night Miku.png", "The Module is based directly off the outfit worn by Miku for her guest appearance in the video game Persona 4: Dancing All Night. It consists of a white, skintight turtleneck with four large, black buttons adorned with various icons and a musical note symbol in the center, a black miniskirt with suspenders, black gloves, and black skintight boots with icons on the sides. Additionally, Miku wears black wire headphones with icons on the pads and the wire attaching to the skirt.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3709, "Pajama Party Miku", "Pajama Party Miku", "putidevil", "/miku_monday/Pajama Party Miku.png", "The Module's attire consists of a white pajama top with teal stripes on the sleeves, teal rims, and a teal bow with white puffballs hanging on strings, and white pajama pants with teal hues and white ribbons on the bottom. Additionally, Miku's twin-tails are held in knotted rings with white hairbands.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3164, "Pansy", "Pansy", "TNSK", "/miku_monday/Pansy.png", "The Module's attire consists of black headphones with a white handle and a yellow and black pansy attached to the right side, a light tan dress with black trimmings that becomes black in the skirt area that is pansy-shaped with yellow trimmings, a black ribbon, a tan open-vest with speaker-like decorations with golden trimmings, black wristbands with yellow and black pansies, a mint green bodysuit with openings on the sleeves and upper legs and black stripes also on the upper legs, and black tornado-like boots with yellow trimmings and soles. Additionally, Miku's twin-tails become a split-end with a whole split on each side.", "[\"Weekender Girl\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3090, "Patchwork", "Patchwork", "ryono", "/miku_monday/Patchwork.png", "The Module's attire consists of a white sleeveless collared shirt with light-grey linings on the front, a light turquoise necktie, long navy blue gloves, matching shorts with three frilled layers, stocking boots with light turquoise heels, and red and blue ribbons with white holi flower designs. Additionally, Miku's hair and eyebrows become olive green and her twin-tails become thinner, more zigzagged, and are placed under her head.", "[\"Puzzle\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7487, "Peanut no Boushi", "Peanut no Boushi", null, "/miku_monday/Peanut no Boushi.png", "The Module consists simply of a broken peanut shell acting as a hat.  Miku's default outfit is used as a base for this Module.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3509, "Phantom Thief Miku", "Phantom Thief Miku", "booota", "/miku_monday/Phantom Thief Miku.png", "The Module's attire consists of a black jacket with a diamond-checkered collar and cuffs, a light crimson dress with white stripes and frills held with a white waist belt, a dark heliotropeish grey collared undershirt, a white tie, black fingerless gloves, long stockings, pink shoes, and the headwear includes a small black top hat with a diamond-checkered mid-section and light crimson and black flower-like hairbands. Additionally, Miku's hair and eyes become light turquoise and her twin-tails become slightly shortened and less curved.  In Project Mirai, the shoes match the dress and hairbands.", "[\"Piano × Forte × Scandal\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3261, "PIANO*GIRL (Module)", null, "Y-oji", "/miku_monday/PIANO*GIRL (Module).png", "The Module's attire consists of a coffee brown beret with white stripes and a warm grey and strong amaranth bow on it, a coffee brown dress with white stripes on the bottom featuring dark brown musical notes, white frills, and a coffee brown bow on the back, a white collared shirt with cuffs and coffee brown trimming and buttons, a red necktie with warm grey trimming, dark stockings, and strong amaranth Mary-Jane high-heels. Additionally, Miku's hair becomes opal with light tangelo hues on the midsection, and has an upwards cowlick sticking out of her hair.  In the Arcade Future Tone series and MegaMix, the bow becomes a matching color to the attire, the center stripe of it, the necktie and the high-heels become greyish red, and the notes seen in MegaMix become a slightly lighter shade.", "[\"PIANO*GIRL\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3156, "Pierretta", "Pierretta", "nezuki", "/miku_monday/Pierretta.png", "The Module's attire consists of a dark brown hoodie with cat ear bulges, red edge trimming and straps, and white frilled trimming, all tied with a white headband, a red dress with petal-like flaps, white edge frills, and yellow center stitching, a white and black under-dress with a white tutu-like skirt with black lace, a black tail charm attached to a waist belt, a matching choker with a ribbon, red detachable sleeves with white frilled cuffs, vertically striped black and white striped stockings, and red high-heels with white puffballs on the tips. Additionally, Miku's hair becomes dark turquoise and waist-lengthened with diagonal bangs, her twin-tails are tied on the lower-back portion of her head, her eyes become yellow, her nails are red to match the rest of the attire, and she has a painted pink teardrop under her left eye.", "[\"Cat Food\",\"Step Forward\",\"Let Me Lose Myself in The Black Note\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3048, "Pink Pops", "Pink Pops", "Obiyuki", "/miku_monday/Pink Pops.png", "The Module's attire consists of orange sunglasses, a pink crop-top with fur coating and blue button in the center, long pink gloves, short dark denim shorts with buttons, and tan boots also with buttons on one side each. Additionally, Miku's twin-tails become much shorter and wavier, and are held with yellow and green button hair pins, and her bangs are parted to the right.", "[\"Look This Way, Baby\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3051, "Pink Pops Alt.", "Pink Pops Alt.", "Obiyuki", "/miku_monday/Pink Pops Alt..png", "The Module's attire consists of a pink crop-top with fur coating and blue button in the center, long pink gloves, short dark denim shorts with buttons, and tan boots also with buttons on one side each. Additionally, Miku's twin-tails become much shorter and wavier, and are held with yellow and green button hair pins, and her bangs are parted to the right.  This alternate version of Pink Pops moves the orange sunglasses to hang on the center of the crop-top.", "[\"break;down\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2845, "Pirate", "Pirate", "Kiyoto", "/miku_monday/Pirate.png", "The Module's attire consists of a red pirate jacket with yellow trimmings, matching detachable sleeves with black frills, a reddish-brown shirt with a white frill on the bottom, a black skirt, brown gloves, a black waistband, brown boots with red and yellow stripes on top of them, and a black pirate hat with yellow trimming. Additionally, Miku wears her hair loose.", "[\"White Dove\",\"Perico Space Shipper\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4043, "Pizzicato", "Pizzicato", "amemura", "/miku_monday/Pizzicato.jpg", "This Module's attire consists of a simple is of a simple white night gown and an anklet on the left ankle. She also goes barefoot, as it is meant to give a sorrowful and lonely appeal. Additionally, her hair and eyes become light gray-blue, her bangs are swept to the left, and her twin-tails become shorter and thinner and are held with white ribbons.", "[\"Patchwork Staccato\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2841, "Plug-In", "Plug-In", "Masato Ishioh", "/miku_monday/Plug-In.png", "The Module's attire consists of a dark purple full body cyber-suit complete with matching add-ons on the ankles, a white handkerchief with a purple jewel-piece attached to it, white gloves with blue dots, and blue triangular add-on flaps attached to the suit and white circular headphones with black trimmings. Additionally, Miku wears her hair loose.", "[\"Star Story\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3074, "Powder", "Powder", "Ichikai Hano", "/miku_monday/Powder.png", "The Module's attire consists of a white beret with a small pink bow at the base, white headphones, a light pink sleeveless winter dress with yellow buttons and two white vertical stripes, a white scarf, detachable sleeves with light pink cuffs, a white skirt with a pink stripe on it, and white boots with light pink cuffs and soles. Additionally, Miku wears her hair loose.", "[\"When First Love Ends\",\"Finder\",\"Strobe Nights\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2969, "Princess", "Princess", "wadaka", "/miku_monday/Princess.png", "The Module's attire consists of a pink jacket with puffy sleeves, a bow, and white frills and trimming, a light yellow undershirt, a pink skirt with white frills, mismatching detachable sleeves with the left sleeve pink and light yellow and the right sleeve dark and light pink, light yellow and light pink striped stockings, pink boots with white frills and golden brown stripes, dark and light pink mic-attached headphones with a small crown and red heart ornament attached to it and a light yellow heart on the ear-pads, and pink hairbands, and Miku's nails match the rest of the attire.", "[\"VOC@LOID in Love\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3486, "Princess Blanche", "Princess Blanche", "Kazeno", "/miku_monday/Princess Blanche.png", "The Module's attire consists of a white knee-length gown with puffed shoulders, gold design stitching on the hem, sleeves, and collar, matching ribbons that hold Miku's twin-tails with strands sticking out on top, a light cyan broach on the bottom of the collar, a dark purple ribbon tied around the waist, white stockings, glass high-heels with pink roses on the tips, and a small silver tiara with flower designs. Additionally, her hair becomes a light opal, her nose-bang is pointed to the right, the rest of her bangs are gathered and become shorter, and her nails are painted white.", "[\"Cendrillon\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3678, "Puffy Pastels", "Puffy Pastels", "Yunii", "/miku_monday/Puffy Pastels.png", "The Module's attire consists of a light pink crop-top with a dark pink hem held with a red tie, a white frilled shoulder straps with red stripes, white polka dots on the light pink top, and white and sky blue layers under the top, white shorts with red stripes on the hems and three pink bows on each side, light pink leg warmers with white polka dots, pink no-show socks with little red bows, and a red ponytail holder that is decorated with ornaments. Additionally, Miku's hair and nails become cyan and wears a side ponytail on the left side.", "[\"Glory 3usi9\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4045, "Pumpkin Dream", "Pumpkin Dream", "hachi", "/miku_monday/Pumpkin Dream.jpg", "The Module's attire consists of a white, collared shirt with puffed shoulders and teal buttons, a teal bowtie, white gloves with black cuffs, black shorts with white cuffs and black suspenders, a black and white striped waist belt, teal and black striped stockings, and black boots. Additionally, Miku's hair and eyes become orange with her twin-tails that reach her thighs and bleed into turquoise towards the bottom, and she wears a mini black top hat with a teal stripe on the center.", "[\"Humorous Dream of Mrs. Pumpkin\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2875, "Punk", "Punk", "yamisawa", "/miku_monday/Punk.png", "The Module's attire consists of a black peaked cap with red and pink stripes and a gold star in the center, white headphones with black stars on each side, a black choker with a red stripe, a navy blue and black bra with a star on the left shoulder strap, and another star on the lower left side of the stomach, black shorts held by a brown belt, blue-green short tights, fishnet leggings with black cuffs with red accents, matching elbow length leather fingerless gloves, and black boots. Additionally, Miku wears her hair loose that reaches to her thighs, and black nail polish to match her attire.", "[\"Love is War\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3127, "Racing Miku 2010 Ver.", "Racing Miku 2010 Ver.", "redjuice", "/miku_monday/Racing Miku 2010 Ver..png", "The Module is based off the attire worn by promotional models of the race team, Good Smile Racing during the Super GT 2010 season. It consists of orange headphones with a black handle, a short orange jumpsuit with white on the chest area and center section, as well as red trimmings, logos of Good Smile Racing and Crypton Future Media, orange tool bags on both sides of the suit, long, orange gloves with white and red trimmings and a grey wristband on the left wrist, and thigh high, white boots with red trimmings and grey heels. Additionally, Miku's twin-tails become thinner and are held with orange and red hairbands.", "[\"Time Limit\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3134, "Racing Miku 2011 Ver.", "Racing Miku 2011 Ver.", "Yuichi Murakami", "/miku_monday/Racing Miku 2011 Ver..png", "The Module is based off the attire worn by promotional models of the race team, Good Smile Racing during the Super GT 2011 season. It consists of black headphones, a white bodysuit with a black, sleeveless, see-through coat attached to the bodysuit with neon-turquoise trimmings and grey accessories on the bottom corners of the suit, a neon-turquoise necklace, neon-turquoise bands on Miku's thighs with grey and black accessories featuring turquoise and red lights, a silver accessories on the upper chest, long black gloves with turquoise stripes that extend up to Miku's upper arms, and black boots with silver cuffs on the openings, and silver tips and heels with turquoise trimmings. Additionally, Miku's hair gains additional cowlicks, and her twin-tails gain light blue hues and are held by see-through dish-like hairbands, and her serial code \"01\" is now in neon-turquoise with the \"1\" being part of the stripe from the left glove.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3144, "Racing Miku 2012 Ver.", "Racing Miku 2012 Ver.", "GAN", "/miku_monday/Racing Miku 2012 Ver..png", "The Module is based off the attire worn by promotional models of the race team, Good Smile Racing during the Super GT 2012 season. It consists of white headphones with attached-on earrings, a grey and black tiara with a purple light on the center, a white cyber crop top with small black plates and neon turquoise straps, a grey collar with turquoise trimmings and a small, turquoise, see-through tie connected on, grey plates around the body with an opening in the center with turquoise linings, long, white fingerless gloves, a white skirt with turquoise dials, a black plate on the center, and see-through fabric on the bottom center with turquoise trimmings, white shorts with turquoise trimmings, black and white thigh-high boots with purple lights on the top and bottom and turquoise trimmings and soles, and Miku's twin-tails are held with white and black circular hairbands. Additionally, her hair is more thicker.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4204, "Racing Miku 2016", "Racing Miku 2016", "Shigeto Koyama", "/miku_monday/Racing Miku 2016.jpg", "The Module is based off the attire worn by promotional models of the race team, Good Smile Racing during the Super GT 2016 season. It consists of a white cropped dress with red and orange stripes traveling down from the left to the right side and the Good Smile Racing logo on the chest, orange-red gloves with \"Good Smile Racing\" being printed on the right glove in white and multicolored stripes on the left glove, white shorts, orange-red boots with Crypton Future Media's logo on the right boot and multicolored stripes on the left boot, and white headphones with multicolored pads. Additionally, Miku has a red highlight on her left bang, her twin tails are tied with white hairbands with orange stripes, and her nose bang has two sections.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3250, "Rainbow Lines", "Rainbow Lines", "TNSK", "/miku_monday/Rainbow Lines.png", "The Module's attire consists of a white shoulder-cut dress with black on the back side, blue speakers on the sides, three rainbow accents reaching down to the legs, and seven colored bows that are aligned straight down. There is also a sky-blue choker, black and red stockings, white boots with black hems and rainbow soles, and black headphones with white earpads with rainbow accents and black ornaments that give them the appearance of the eighth note (♪). Additionally, Miku's twin-tails become thinner and swirl towards the bottom, her hair overall becomes sky blue with dark hues at the bottom, her bangs have additional strands, her eyes become blue, and her fingernails are painted different colours of the rainbow.  In Project DIVA Arcade Future Tone, its PlayStation 4 port, and MegaMix, the tips of the boots become much shorter, giving them a more hoof-like appearance, and her eyes match her hair.", "[\"Glory 3usi9\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4047, "Raspberryism", "Raspberryism", "AKIAKANE", "/miku_monday/Raspberryism.jpg", "The Module's attire consists of a moderate raspberry sleeveless top with a yellow hem, matching detachable sleeves, a raspberry red collar with yellow hems, moderate raspberry fingerless gloves with dark cuffs and vivid apple green dots on the back of the hands, dark raspberry shorts with four vivid apple green buttons and moderate raspberry and vivid apple green cuffs, matching stockings, dark raspberry boots with vivid apple green laces and yellow soles, a moderate raspberry headband, and earrings. Additionally, Miku's hair becomes forest green with moderate raspberry hues and her twin-tails reach only up to her chin, her front bangs become thick and extend towards her eyebrows while the rest of them are thin, her eyes become moderate raspberry with dark teal hues and lime green pupils, and her nails become vivid apple green.", "[\"Raspberry*Monster\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3263, "Regret", "Regret", "Yamako", "/miku_monday/Regret.png", "The Module's attire consists of a greyish cobalt blue vest-coat, a white dress with a black under-layer and a white petalled collar, a maroon choker, a waist belt with a black bow, a maroon wristband, matching pantyhose, black Mary Janes with white soles and a button, and maroon petal-like hairbands. Additionally, Miku's hair and nails become a pale turquoise, her twin-tails become shorter and more spaced out, and her bangs become slightly shorter and are gathered vertically.", "[\"Karakuri Pierrot\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 6783, "Reverse rainbow (Outfit)/Miku", "reverse rainbow", "tom", "/miku_monday/Reverse rainbow (Outfit)/Miku.jpg", "The Outfit's attire consists of a long white collared coat with teal inner-fabric and gray stripes on the collar and end sleeves, and a teal bow on the back, a teal necktie with a yellow droplet clipped on, a white dress with light and dark gray stripes on the bottom and two upside-down triangle cuts revealing teal fabric, teal three-finger rings with a white and teal poppy on the middle fingers and two dandelions on the index and ring fingers, and black boots with teal stripes on the openings and teal soles. Additionally, Miku wears white headphones with a rainbow on each of the side handles and eighth notes (♪) on the earpads.", "[\"reverse rainbow\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3142, "Ribbon Girl", "Ribbon Girl", "anmitu", "/miku_monday/Ribbon Girl.png", "The Module's attire consists of a pale amaranth cardigan hoodie with inner flannel fabric, white double stripes on the sleeves and cuffs, an emblem on the left side of the cardigan as well as various small ribbons attached, a light brilliant red bow tied on the right cuff, and a pale amaranth bow on the back, a very pale vermilion collared shirt, a dark purple tie with white and violet stripes and a pin with a light blue M design, light brilliant red headphones with mint green bow designs on the ear-pads and a \"01\" logo on the left pad and a wire on the right pad traveling down to the cardigan pocket, a greyish turquoise pleated skirt with white stripes, white high-socks with three small pale amaranth bows on each sock, and pale amaranth high-cut sneakers with light brilliant red laces and soles, white bows with stitching, and flannel patches. Additionally, Miku's hair is worn loose with a portion of it held in a \"half-up\" ponytail with a pale amaranth bow attached to a purple hair tie.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2985, "Rin Style", "Rin Style", null, "/miku_monday/Rin Style.png", "The Module attire is based off of Kagamine Rin. It consists of a short white sleeveless shirt with small yellow frills, a yellow G-clef (Treble-clef) printed on the shirt, a black collar, a yellow handkerchief, black detachable sleeves with yellow trimmings and green interface bars, black shorts held by a yellow belt with a matching belt chain, black legwarmers with yellow trimming, white shoes with yellow soles, and white headphones with a big bow attached to it.", "[\"Song of Life\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3214, "Rin-chan's ＃1 Fan", "Rin-chan's #1 Fan", "Hiro Tamura", "/miku_monday/Rin-chan's ＃1 Fan.png", "The Module's attire is based off of Kagamine Rin. It consists of white headphones with turquoise and yellow stripes on the sides of the handle, black covers, and a yellow Rin head with a white \"02\" on the earpads, a white tank top with yellow stripes on the sides, a black collar, a short yellow tie, a orange pouch held by a white shoulder strap, short black detachable sleeves with yellow trimmings, an orange armband on the left arm, short black shorts held with an orange belt, an orange belt strap, a small Rin doll held on the right leg, black legwarmers with yellow trimming, and white shoes with yellow soles. Additionally, Miku's bangs are held in a similar style to Rin's with two hairclips parting the bangs to the left and an additional two on the right, and her twin-tails are held with hairbands that have small versions of Rin's iconic bow.", "[\"Rin-chan Now!\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4052, "Rockin' Stone", "Rockin' Stone", "Nidy-2D-", "/miku_monday/Rockin' Stone.jpg", "", "[\"Cool Medley - Cyber Rock Jam\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3121, "Rolling Girl (Module)", "Rolling Girl", "Minakata Laboratory", "/miku_monday/Rolling Girl (Module).png", "The Module's attire consists of a dark warm brown open cardigan with a white blouse underneath, a sailor-style collar matching the cardigan with blue trimming, and a blue neckerchief on the collar. The lower half includes a dark warm brown pleated skirt, matching knee-high socks, and white indoor shoes with a light blue streak at the tip. Additionally, Miku's hair and eyes are now dark blue, and her twin-tails are slightly shorter, reaching knee-length.", "[\"Rolling Girl\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7558, "Romeo and Cinderella (Outfit)/Miku", "Romeo and Cinderella", "nezuki", "/miku_monday/Romeo and Cinderella (Outfit)/Miku.jpg", "The Outfit's attire consists of a black strapless dress with lace lining much of the middle of the blouse, a black bow on the back, an additional layer on the bottom, and laces on hems, short black gloves with red-violet bows with black polka dots, a white detachable collar, small, black flower tattoos on the left ankle, and black high-heels with ankle straps. Additionally, Miku's hair becomes pale blue and is worn loose with a black headband with a large red-violet corsage on the left side.", "[\"Romeo and Cinderella\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3448, "Rosa Bianca", "Rosa Bianca", "Ittomaru", "/miku_monday/Rosa Bianca.png", "The Module's attire consists of a white and green eye mask, a white ball gown with olive-green accents, puffed shoulders, a white collar with a white rose in the center, white gloves with olive-green crosses on the back, white laced under-fabric that is exposed in the center, greenish-grey stockings, greyish olive-green high-heels, and green bows with white roses perched on. Additionally, Miku's hair and eyes become olive-green, her twin-tails are thinner and spiral downwards with turquoise hues, she has a few strands of hair, and her eyebrow-lengthened bangs become thickened and gathered.  Beginning with Project DIVA Arcade Future Tone, her skin becomes paler, and in F 2nd and X, the eye mask has no shades and the high-heels become turquoise.", "[\"Cantarella\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3449, "Rosa Notte", "Rosa Notte", "Ittomaru", "/miku_monday/Rosa Notte.png", "This alternate version of Rosa Bianca changes the color of Miku's attire from white to black, with the olive-green also being more darker. Its attire consists of a black and green eye mask, a black ball gown with dark olive-green accents, puffed shoulders, a black collar with a black rose in the center, black gloves with dark olive-green crosses on the back, olive-green, laced under-fabric that is exposed in the center, grey stockings, dark olive-green high-heels, and black roses perched on her green bows. Additionally, her skin becomes lightened, her hair becomes a dark olive-green, her twin-tails are thinner and spiral downwards with a few hair strands, and she wears pink lipstick.", "[\"Cantarella\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3146, "Running Miku", "Running Miku", "hekopon", "/miku_monday/Running Miku.png", "The Module's attire consists of pink earphones with a cord hanging around the back of the head, a necklace, a yellow and white track jacket with a pink zipper and teeth, a teal crop top with black trimmings and a number layer with the number \"39\" on it, a black bracelet, teal and white shorts with a black and pink hem and V-cut openings on the sides, pink sneakers with blue sides and yellow laces, and pink and yellow band-aids on both knees. Additionally, Miku's twin-tails are held with thin black hairbands.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3065, "Saihate Miku", "Saihate Miku", "Kobayashi Onyx", "/miku_monday/Saihate Miku.png", "The Module's attire consists of a black school blazer with a pink flower attached on, a white collared shirt, a black necktie, a black skirt, black socks, and brown loafers. Additionally, Miku's hair becomes a dark blue.", "[\"Saihate\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3088, "Sakura Miku", "Sakura Miku", "putidevil", "/miku_monday/Sakura Miku.png", "The Module's attire is a pink version of Miku's default outfit. It consists of a white sleeveless shirt with pink edge trimmings, a dark pink tie with a printed white Sakura petal design and two light green stripes, pink detachable sleeves with white trimmings and petal-like cuffs, a pink skirt with white edge trimming, a matching belt strap, two cherries on the back of the shirt with the stems acting as a bow, and pink futuristic footwear with white trimming and soles. Additionally, her hair and nails become pink with the hair having white and dark pink Sakura petal designs on her left bang and twin tails, which are being held with white and pink versions of her futuristic hairbands, her headphones' ear-pads become white Sakura petals with hot pink oval illuminations, the handle and attached mic also become pink with two white stripes on the mic, and her eyes become dark pink.", "[\"The secret garden\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3009, "School", "School", "Ichika Eto", "/miku_monday/School.png", "The Module's attire consists of a short white school blazer that includes a school emblem that features a leek on the left sleeve, a light-cyan collared shirt, a turquoise tie, two leek-shaped hairpins, a white skirt, black socks, and brown loafers.  In Project DIVA F 2nd and X, Miku wears her default headphones instead of the DIVA-styled ones.", "[\"That One Second in Slow Motion\",\"Sakura no Ame\",\"One-Sided Love Samba\",\"Love's note\",\"I Really Do Understand\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3057, "School Noble", "School Noble", "Eika", "/miku_monday/School Noble.png", "The Module's attire consists of a moderate scarlet collared dress shirt with puffed sleeves, light brilliant amber trimming, and a light brilliant gold bow, a white and greyish phthalo blue frilled skirt, grey stockings, moderate scarlet socks with white trimming on the cuffs, greyish phthalo blue high-heels, and moderate scarlet headphones with a bow and neon yellow swirls on the ear pads, resembling a bass clef. Additionally, Miku wears her hair loose.  In Project DIVA F 2nd and X, the rest of the attire is moderate red, the stockings become slightly darker, and the frilled skirt and high heels become dark blue.", "[\"Cantarella\",\"Master of Puppets\",\"Catch the Wave\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4041, "Sea Lily", "Sea Lily", "Awashima", "/miku_monday/Sea Lily.jpg", "This Module includes a short-sleeved one-piece dress reaching until about 1/4 of the legs that's white from the collar and sleeves to the middle of the chest, with the rest being blue. The collar includes two buttons and the skirt includes purple and white at the edge, and with blue tied ribbons and white ruffles on each side on the inside of the skirt reaching the knees. The middle of the dress has purple buttons on each side connecting a white belt-like strap on the back. This Module has no shoes to resemble the bottom of the sea. Additionally, Miku's hair becomes brighter turquoise with messier bangs and no twin-tails, reaching just below the shoulders, with purple and white striped ribbon-like ties on each side, and her nails become darker and deeper blue.", "[\"Tale of the Deep-sea Lily\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3096, "Shiny", "Shiny", "Atsuya Uki", "/miku_monday/Shiny.png", "The Module's attire consists of a light white shirt with black trimming and a red ribbon, black denim shorts, shoes with a red soles, and a red and black ribbon on the left wrist. Additionally, Miku's hair becomes sky blue with her bang parted to the right held by a hairclip and her twin-tails are held with black and red ribbons.", "[\"Sekiranun Graffiti\",\"Glory 3usi9\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4048, "Silent Voice", "Silent Voice", "tokiti", "/miku_monday/Silent Voice.jpg", "The Module's attire consists of a dark grey unzipped hoodie sweater with turquoise hems, a stripe on the left chest, short black and white checkered rims, and two stripes at the bottom for pockets, a white collared shirt, a light turquoise bowtie, a black skirt with teal stripes on the hem, long dark grey boots with a white stripe on the hem and turquoise soles, black headphones with a teal wire on the right ear-pad that travels down to the left pocket showing a matching cassette, and a small black heart-shaped tattoo on the right thigh. Additionally, Miku's hair becomes dark cyan and unruly, her hairbands are similar, if not the same, to the ones from her default outfit, and her irises are different colours, having the left eye yellow and the right eye red.", "[\"Strangers\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3259, "Siren", "Siren", "wogura", "/miku_monday/Siren.png", "The Module's attire consists of a sequin yellow dress with a purple stripe going down the center, purple frills and a purple bow on the back, white frills under the dress, purple gloves with frilled cuffs, a pearl necklace that is tied with a purple bow on the back, dark stockings, and yellow high-heels with purple soles. Additionally, Miku's hair thickens with strands spaced out and is worn with a purple bow with pearls in the center placed on the left side.", "[\"This is the Happiness and Peace of Mind Committee\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2966, "Sleepy Time", "Sleepy Time", "Rag", "/miku_monday/Sleepy Time.png", "The Module's attire consists of a short-sleeved, pink plaid pajama shirt with white frills, and a red bow, matching pajama shorts, and pink slippers with white puffballs. Additionally, Miku's twin-tails are held with white hairbands.", "[\"Marginal\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3012, "Snow", "Snow", "SAB", "/miku_monday/Snow.png", "The Module's attire consists of a navy blue snow hat with a large black trimming, silver headphones, a sleeveless navy blue coat with a gold zipper and a black collar and trimming, a matching skirt, black gloves with gold trimming, gold bracelets with puffballs, black socks with gold trimming, and black boots with gold zippers and soles. Additionally, Miku wears her hair loose.", "[\"Strobe Nights\",\"Catch the Wave\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3225, "Solitude", "Solitude", "Tama", "/miku_monday/Solitude.png", "The Module's attire consists of a black shirt, a blue jean jacket, a red belt, a white frilled skirt with three layers and red trimming, long red socks, and brown boots. Additionally, Miku's hair is slightly shortened.", "[\"Torinokocity\",\"Step Forward\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3100, "Sonic Style", "Sonic Style", "Yuji Uekawa (SEGA)", "/miku_monday/Sonic Style.png", "Miku's Module is based off the character Sonic the Hedgehog from the franchise of the same name. It consists of a blue sleeveless sweater with its hoodie being based off Sonic's quills, complete with ears with peach canals. The sweater also includes back spines, turquoise edge trimmings, and a zipper in the style of the franchise's Rings with turquoise teeth. There is also a hot pink crop-top with a black edge trimming, white oversized gloves with sock-like cuffs, blue baggy pants with a turquoise waistband, a turquoise belt chain, a symbol of the Sonic franchise's 20th anniversary, or the Sonic the Hedgehog logo with Modern Sonic's pose from Sonic Generations in 2D in the Arcade version, stitched on the bottom left side of the left leg, the first name of the character written in yellow on the back of the pants, and a blue tail attached on, and finally, the hedgehog's iconic red sneakers with white cuffs, white straps held by a golden buckle on each shoe, and grey soles.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2987, "Space Channel 39", "Space Channel 39", "Mayumi Moro (SEGA)<ref>{{Cite web |url=https://miku.sega.jp/pjd/spchan39.html |title=初音ミク -Project DIVA- |publisher=SEGA |language=Japanese |accessdate=4 March 2025", "/miku_monday/Space Channel 39.png", "Miku's Module is based off the Space Channel 5 series. It consists of a short, black, space-age sleeveless crop top with a long round collar with teal trimming and a pink Space Channel 5-esque logo with the number 39 on it, matching short shorts, translucent detachable sleeves with teal trimmings, black gloves, a black jetpack, and black thigh-high boots with teal trimming, heels, and soles. Additionally, Miku wears purple headphones and her bangs are parted to the right, reminiscent to Space Channel 5<nowiki>'</nowiki>s main character, Ulala.  In Space Channel 5 VR: Kinda Funky News Flash!, the detachable sleeves were removed, the shorts were changed into a skirt, and white trimming were added to the top part of the heels.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2981, "Space Channel 5", "Space Channel 5", null, "/miku_monday/Space Channel 5.png", "Miku's Module is based off the character Ulala from the Space Channel 5 series. It consists of a short, white, space-age sleeveless dress with a long round collar with silver trimming and the Space Channel 5 logo, a matching skirt, white gloves, a silver jetpack, a teal blaster held on her right leg, and white boots with orange heels and soles. Additionally, Miku wears white headphones, her hair becomes hot pink, and her eyes become blue.", "[\"I'll Miku-Miku You♪ (For Reals)\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3086, "Spacey Nurse", "Spacey Nurse", "naralika", "/miku_monday/Spacey Nurse.png", "The Module's attire consists of a white space-age nurse outfit with a stethoscope-like belt holding the dress, white gloves, grey-blue stockings with a strap on the left thigh with a pill-like container on it, white high heels with red tips, and a white nurse cap with a diagonal red stripe. Additionally, Miku's hair becomes a bluish-white with her twin-tails swirling from the top down and her bangs swept to the left, and her eyes become red.  In the high-definition games, her eyes are vivid rose.", "[\"Love-Colored Ward\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3033, "Spiritual", "Spiritual", "KEI", "/miku_monday/Spiritual.png", "The Module's attire consists of a row of white, light rose, and turquoise flowers around Miku's head, a white translucent coat with magenta trimming, a string of flowers around her chest, white detachable sleeves with turquoise trimming and turquoise flowers banded on the top part of the sleeves, a teal skirt with white trimming and flower designs and a white and teal triangular belt chain, and white thigh-high socks and loafers with turquoise trimming, flowers, and soles with turquoise anklets featuring white flowers. Additionally, her headphones become white with a magenta half-circle on the earpads and two stripes on the attached mic, her futuristic ribbons become turquoise and white, and her eyes become a brilliant cerise.", "[\"Aikotoba\",\"The First Sound\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2960, "Star", "Star", "SEGA", "/miku_monday/Star.png", "The Module's attire consists of a sleeveless gray shirt that is separated into different flaps at the bottom with turquoise trimmings and pink jewel pieces, a turquoise bow with a jewel piece at the center, a black skirt with turquoise trimming, grey boots with turquoise trimming and soles, black fingerless gloves with turquoise trimming, and golden bracelets, and a turquoise bow on the back of the skirt. Additionally, Miku has black diamond shaped earrings attached to her headphones.", "[\"Grumpy Waltz\",\"ZIGG-ZAGG\",\"Time Limit\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3160, "Star Vocalist", "Star Vocalist", "NIL", "/miku_monday/Star Vocalist.png", "The Module's attire consists of black open-handle mic-attached headphones with two hot pink rectangles and an attachment on the handle that clips on two hot pink highlights on the left twin tail, a pink dress with light hues, a thin triangular cut going up to the mid-section, and a black logo design, a black enamel-like plate on the top part with pink system lights, a clear strap attached to the plate, a small clear tie, white detachable sleeves with black trimming and the left sleeve having the top part see-through, and Miku's \"01\" serial code in black, black fingerless gloves, a white skirt with black trimmings and small black squares, a clear belt strap, and black boots with white cuffs and pink lights and soles. Additionally, her hair and bangs become slightly unruly and her nails become hot pink.", "[\"Freely Tomorrow\",\"Systematic Love\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3162, "Star Vocalist Alt.", "Star Vocalist Alt.", "NIL", "/miku_monday/Star Vocalist Alt..png", "The Module's attire consists of black open-handle mic-attached headphones with two hot pink rectangles and an attachment on the handle that clips on two hot pink highlights for the left twin-tail, a pink dress with light hues, a thin triangular cut going up to the mid-section, a black enamel-like plates on the top part of the dress with pink system lights, a clear strap attached to the plate, a small clear tie, and a black logo design on the dress, white detachable sleeves with black trimming and the left sleeve having the top part see-through, including Miku's \"01\" serial code in black, black fingerless gloves, a white skirt with black trimmings and small black squares, a clear belt strap, and black boots with white cuffs and pink lights and soles. Additionally, her hair and bangs become slightly unruly and her nails become hot pink.  This alternate version of Star Vocalist has her hair become a very pale yellow and her eyes greyish-purple.", "[\"Freely Tomorrow\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7527, "Steampunk", "Steampunk", null, "/miku_monday/Steampunk.png", "The Module consists of a greenish-gray jacket with red cuffs and stitching on the sleeves, a dark-brown dress with golden accessories, a dark-brown choker, a teal waistbelt with a golden cogwheel, an additional red waistband, dark-brown skirt with light-brown, striped frills, dark-brown belt straps on the thighs, and brown zipper boots with gray openings and two cogwheels on each side.  Additionally, Miku wears reddish-brown goggles with light-brown covering and gold designs on the lenses, most of her bangs are cut horizontally, and her twintails become more thinner and become wavy towards the ends and are held with two, large gold cogwheels.  Miku also holds a gold Sennheiser-esque microphone with a gold cogwheel in her right hand.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7580, "Sugar*Soldier Uniform", "Sugar*Soldier Uniform", "Mayu Sakai", "/miku_monday/Sugar*Soldier Uniform.jpg", "Miku's Outfit is based off the character Makoto Kisaragi from the manga series Sugar*Soldier. It consists of a mustard-yellow school blaze, a white  collared long-sleeved shirt, a red-violet bowtie with black and white stripes, a red-violet plaid pleated skirt with black and white stripes, black socks, and brown loafers. Additionally, Miku's hair is worn loose with some strands braided around her head, and a small magenta bowtie with white polka dots on the right side of her head.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3202, "Summer Memories", "Summer Memories", "guitar", "/miku_monday/Summer Memories.png", "The Module's attire consists of a white sunhat with a sky blue stripe around the center, a white sailor dress with sky blue edge trimmings, a matching collar, a small light cornflower blue necktie, long deep blue socks, and white shoes with a sky blue stripe and soles. Additionally, Miku's hair becomes light cornflower blue with her twin-tails tied with black hair ties on the center back of her head and surpassing her waist. She never wears nail polish.  In Project DIVA Arcade Future Tone, its PlayStation 4 port, and MegaMix, the trimmings and stripe become a cornflower blue, the socks become a very dark blue, and the necktie, shoe designs, and hair become a brilliant blue.", "[\"Time Machine\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7572, "Sunset", null, "Sayopon (SEGA)", "/miku_monday/Sunset.jpg", "The Outfit's attire consists of a white sleeveless dress with a navy blue sailor collar trimmed with a single white line, and three buttons placed evenly on the front of the dress, a navy blue necktie, and black flats. Additionally, Miku's hair becomes sea blue, her bangs are parted to the right, and her twin-tails become short, spiraled pigtails tied below her head.", "[\"glow\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3287, "Supreme", "Supreme", "redjuice", "/miku_monday/Supreme.png", "The Module's attire consists of a white one-piece dress with a small black ribbon on the top-center and frills on the hips, a black bracelet on the left wrist, a black underskirt, black stockings with petal-like openings, black Mary-Jane pumps, and large black bow ribbons with moderate scarlet feathers being attached to the right bow and a hairband tied to the left. Additionally, Miku's twin-tails become wavier, she has her bangs parted over to the left, and she has extended side tails.  In Project Mirai, her hair becomes brightly-colored with slightly-dark hues at the center.", "[\"The World is Mine\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3212, "Sweet Pumpkin", "Sweet Pumpkin", "ICA", "/miku_monday/Sweet Pumpkin.png", "The Module is based on an illustration by ICA for the \"Miku LOVES FamilyMart♪ Campaign 4th Happy Halloween★TRICK or MIKU\". Its attire consists of a black top with teal and orange stripes, a purple heart broach with yellow ribbons, and orange hems, puffed orange detachable sleeves with black frills and pearls, orange cuffs with pearls, a pearl waist belt with large white frills, an orange skirt with pearls scattered throughout, black frills with candy, rose, and star patterns aligning on it and purple bows on the sides, black stockings with white bows, orange high-heels with pearls on the hems, a purple heart ornament, and teal heels, and the hair accessories include orange and teal bows with star ornaments dangling from pearls and black bat wings with a moderate mulberry lining, and the bottom having teal bows with orange stripes and pearls connected to the ends. Additionally, Miku's hair becomes a greyish emerald green and her twin-tails are split in the middle.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7529, "Tanabata", "Tanabata", null, "/miku_monday/Tanabata.png", "The Module consists of a dark-pink kosode with orange hues, dark-blue hems, and a white puffy collar, held with a red obi sash, as well as blue detachable sleeves with Milky Way-esque designs, a gray skirt with square designs, a large ribbon with various hues of blue and decorative stars attached on the back, white stockings with flower designs, gray stripes, and petal-like openings, gray sandals, and a dark-blue headband with a red ribbon and a star attached, and a silver UFO attached by an antenna. Additionally, Miku wears her hair down, save for two looped buns that the ribbon holds.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3480, "Trip The Light Fantastic", null, "Oonuma Mon", "/miku_monday/Trip The Light Fantastic.png", "The Module's attire consists of pink headphones, a short yellow and green collared jacket with white cuffs, an orange and white striped dickie with a white collar, and blue necktie, an orange vest with yellow buttons and green stripes, an orange under-dress with green fabric underneath and a blue bow on the center, white gloves, a yellow balloon skirt with multi-colored stripes spread out (with the center green stripe having dark green stripes) and white frills, orange and green stockings, yellow socks, and blue high-heels with red tips and heels. Additionally, Miku's hair becomes more thick and wavy with dark blue hues going down, her twin-tails are held with blue strings, her bangs are cut horizontally,  and her eyes become green with tiny stars on the irises.", "[\"shake it!\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7521, "Tropical Mermaid", "Tropical Mermaid", null, "/miku_monday/Tropical Mermaid.png", "The Module consists of a white, pink, and blue crop top with pearl decorations, a scale-esque skirt with pink, blue, and teal hues and a white ribbon tied on the waist, lavender and pink tailbacks resembling a mermaid's tail, a purple high-heels. Pearls also decorate the Module, appearing as earings, a necklace, bracelets, and anklets.  Additionally, Miku wears purple headphones with pearl designs for the earpads, and includes a purple bow on the right side, and a pink crown and two gold stars with left side. Her hairstyle consists of a two twinbuns, with her twintails becoming more wavy, and has extended sidetails going past her shoulders.  Miku also holds a mini-harp in her left hand.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4051, "Twinkle Star", "Twinkle Star", "Tama", "/miku_monday/Twinkle Star.jpg", "This Module includes a white dress with a pink tie and pink coming out from the bottom of the dress, along with blue and yellow diamonds, and what seems to be a pink shirt underneath with the straps showing. The dress's sleeves hang right below the shoulders and are visible all around the dress, as they are pale yellow underlined with blue. The Module also includes yellow-gold shorts underneath the dress and white thigh highs that are yellow and blue on the top, along with white shoes that are pink on the bottom. There are also bracelets on the wrists.  The Module's facial appearance has Miku's hair being a cheerful turquoise color that turns into cheerful yellow and pink colors by the end, and with star hair ties tying Miku's hair into twintails.", "[\"Cute Medley - Idol Sounds\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3102, "Type 2020", null, "Shirow Miwa", "/miku_monday/Type 2020.png", "Miku's Module is based off the attire she wears in her guest appearance in the video game 7th Dragon 2020. It consists of black headphones with a cornflower blue petal-like handle, a white crop dress-shirt with black stripes going down on the sides and a black centerpiece design on the top of the dress, a dark blue frilled choker with a cornflower blue ribbon, a black frilled skirt with white petal-like edges, a gown with an opening on the front that includes a short cornflower blue layer over a large white layer held with a white fluffy waistband, black frilled wrist cuffs tied with cornflower blue ribbons, long black socks with designed cornflower blue edge trimmings, and cornflower blue high heels tied with blue straps and ribbons, and white fluffy hairbands.  In the high-definition games and Project DIVA MegaMix, the top part of Miku's twin tails become slightly wavy and pointed sideways.", "[\"Though My Song Has No Form\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3117, "Tyrol", "Tyrol", "nezuki", "/miku_monday/Tyrol.png", "The Module's attire consists of a white frilly headband with brown ends, a pale yellow dress with white trimmings showing red, gold, green and brown argyle flower designs on the top and bottom with red and blue stitching, a coffee brown turtleneck shirt underneath the dress, pale yellow socks, and yellow high-heels with brown laces. Additionally, Miku's breast-length hair and irises become a more greenish turquoise, and her hair is tied in pigtails with brown basket-like bands resting on her shoulders. She also carries a brown shoulder bag with a daisy flower design.  In Project DIVA Extend, F 2nd and X, her hair has a slightly lighter color.", "[\"Though My Song Has No Form\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4049, "Ultimate Miku", "Ultimate Miku", "Hidari", "/miku_monday/Ultimate Miku.jpg", "The Module's attire consists of a white, cropped dress with turquoise accents, musical note cuts on the front, and black under-fabric, a white collar with flaps on the back with teal diamond patterns, a turquoise tie with a black emblem, white detachable sleeves with black hems, white and black gloves, dark-gray stockings, and turquoise high-heels with tails from the eighth note (♪). Additionally, Miku's hair gains a light-green hue towards the bottom, her eyes become a golden-brown, wears earrings with dangling black ornaments, and wears a crown with teal stripes, a black emblem, and a gold ornament on the top.", "[\"Beginning Medley - Primary Colors\",\"Ending Medley - Ultimate Exquisite Rampage\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 4033, "Underhanded Green", "Underhanded Green", "Tamotsu Shinohara", "/miku_monday/Underhanded Green.jpg", "The Module's attire consists of a green jumpsuit-like dress-shirt with white on the center and black with a gold hems on the chest area with the words  written in white and gold, a white neck covering, a green star-ornament embedded on the chest, a brown belt with a gold crest that reaches up to the chest, matching white gloves and boots with gold cuffs, white jumpsuit-pants, green stockings with gold hems, and a brown carrier on the right leg holding a shooting-type weapon. Additionally, Miku wears a green helmet with grey pieces on the sides, a gold crest on the top with a green star-ornament embedded, a black visor, and a grey mouth covering.", "[\"Urotander, Underhanded Rangers\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3677, "Urban Pop", "Urban Pop", "Komu24", "/miku_monday/Urban Pop.png", "The Module's attire consists of a light heliotrope sleeveless hoodie sweater with matching strings, yellow inner fabric that includes black polka dots, a matching stripe at the center, the number \"39\" printed on the back blue with yellow borders, a leek zipper, and yellow and dark blue pockets, a white T-shirt, a yellow wristband on the left wrist, cobalt blue rolled-up jeans with white pockets on the front and yellow and black polka-dotted pockets on the back, the words \"diva\" written on the left leg in yellow and light green, and two stars printed on the right leg, a teal belt chain with triangular patterns, orange high-cut shoes with white tips, black straps, and a yellow center, and a red and yellow cap with red eyes and a mouth on the yellow side and multicoloured polka dots on the base worn backwards. Additionally, Miku's hair becomes a greyish malachite green with the hair and fringe becoming spiky, and it is styled in a ponytail that surpasses her thighs with a black hairband.", "[\"Kagerou Daze\",\"Catch the Wave\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3055, "Vintage Dress", "Vintage Dress", "Sakurau / Alice", "/miku_monday/Vintage Dress.png", "The Module's attire consists of a red-violet dress and skirt with the skirt having three pink frills in the center, a red-violet choker, a matching detachable sleeve with chains on the left arm and ribbons tied on the right arm and both legs, a dark red-violet sash with ribbons tied at the waist, red-violet high heels, a little, but medium-sized golden pointy crown with red jewels on Miku's head, and a red-violet flower-pin in her hair.", "[\"Romeo and Cinderella\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3227, "Violet Butterfly", "Violet Butterfly", "riria009", "/miku_monday/Violet Butterfly.png", "The Module's attire consists of a purple dress with black lace designs on the top, black stripes with white stitches on the waist, petal like flaps with dark purple diamond designs hung on the bottom edges, a matching collar, a purple glove with black trimming on the cuff on the left arm, a purple wristband with black trimmings on the right wrist, a black skirt, a purple horse's tail attached on the back of the dress, purple stockings held by a black garter, and dark purple high heels. Additionally, Miku's hair, eyes, eyebrows, and nails become purple with the twin-tails becoming thick on top with the strands in the middle going down with a wavy style and are held with hairbands with black diamond-like designs with white stitches attached on, and she wears pink lipstick.", "[\"Hm? Ah, Yes.\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3016, "VN02", null, "Nagimiso", "/miku_monday/VN02.png", "The Module's attire consists of a silver bodysuit with a black mid-section, black sleeves with magenta trimmings, silver flaps on the bodysuit, black boots with turquoise trimming and silver armoring and long silver add-ons attached to the sides.", "[\"moon\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2957, "Vocal", "Vocal", "tubutuvu", "/miku_monday/Vocal.png", "The Module's attire consists of a yellow sleeveless shirt with black trimming, long black fingerless gloves, a black skirt with yellow trimming and a music walker attached to it, black boots with four teal square lights on top of each boot, and yellow and black headphones with an attached mic on the right earpad. Additionally, Miku's hairstyle is now a left side ponytail tied with a yellow ribbon.", "[\"Packaged\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 2871, "White Dress", "White Dress", "y z k", "/miku_monday/White Dress.png", "The Module's attire consists of a white wedding dress with a frilled skirt and a ribbon, a bubblegum pink ribbon with red trimming in the shape of a heart tied to it, as well as piano designs on the sides, a collar, white finger loop gloves with yellow flowers on the wrists, white thigh-high heeled boots with pink rectangles, headphones with the ear-pads having a dove design, two light green rectangles on the attached mic, a veil, and two roses. Additionally, Miku's hair is gathered in a bun and her nail polish is removed.  In Hatsune Miku: Project DIVA F 2nd, X, and VR Future Live, the dress has no shoulder straps, has a frilled breastplate, and the skirt and collar become slightly different, the boots have light cyan-grey soles and, along with the initial version and Live Stage Producer, grey rectangles, her left finger loop glove loses the flowers and wears a ring, her right one becomes a full glove and has a hot pink wristband with flowers on top, while the initial game has two of them, her fingernails are painted turquoise, the heart ribbon and the rectangles on the attached mic become hot pink, while the initial game is moderate magenta, the bun is held with a braided band, and the heart ribbon has no trimming in said two games.", "[\"Melt\",\"Knight of Light\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3125, "White Eve", "White Eve", "Sayukichi", "/miku_monday/White Eve.png", "The Module's attire consists of a white floral fascinator with fern green leaves in Miku's left hair, a white one-piece dress held by a light-turquoise lace at the waist, matching high-heels with a dark brown buckle attached to the ankle belts, a dark brown necklace with a bell charm, and white hairbands. Additionally, the bottom parts of her twin tails have more pale hues, her irises are different colors, with the left eye yellow and the right eye turquoise, and her nails match the rest of her attire.", "[\"Starduster\",\"Calc.\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3029, "White Gown", "White Gown", "shari", "/miku_monday/White Gown.png", "True to its name, the Module's attire consists of a simple white gown with a white sleeveless see-through overshirt held by a pink ribbon, and vines on the left wrist and right ankle with a different flower on each of them. Additionally, Miku wears her hair loose with a section of it in a left-side ponytail with a lily on a yellow hair clip, and her nose bang splits into two. She is also barefoot.", "[\"Dear\",\"I'm Your Diva\",\"Absolunote\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 7531, "Witch", "Witch", null, "/miku_monday/Witch.png", "The Module consists of a red dress with an apple-like design on the chest, a large, black waistband, green puffed shoulders, black detachable sleeves with red hems, a gray, multi-layered skirt with black frills, black and white, striped stockings, and short, yellow boots. Additionally, Miku wears a black witch hat with a red stripe that includes an apple decoration, and three belt straps, and her twintails become much shorter, reaching to shoulder length. Miku also holds a brown staff with a G-clef symbol in her right hand.", "[]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3076, "Yellow (Module)", "Yellow", "redjuice", "/miku_monday/Yellow (Module).png", "The Module's attire consists of black and yellow headphones with an attached mic in the right, a translucent sleeveless yellow jacket with flower designs that separates towards the bottom exposing Miku's stomach, white jagged trimming on top, and a lemon badge, a white collar, a tie, thick black wristbands with white and red parameters, short white shorts with a black trimming that includes the livetune logo, and yellow boots with black trimmings and soles. Additionally, Miku's bangs become shorter, and her twin-tails become thinner that curl at the bottom that are held with green-yellow hairbands.", "[\"Yellow\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 },
                { 3231, "Zany Hatsune", "Zany Hatsune", "[[PinocchioP]]", "/miku_monday/Zany Hatsune.png", "The Module's attire consists of a white space-age dress-shirt with a v-cut on the bottom with red edging, puffed sleeves with red designs, red circle designs on the middle area with the top and bottom cut off, a yellow ribbon, a gold collar, a yellow sun-like design on the neck area, and katakana letters  written on the back in red, white gloves, a white skirt with a yellow hem on the bottom with a small red rectangle on the center, long red stockings, and white boots with red tips. Additionally, Miku's hair becomes sky blue, her bangs shorten, her twin-tails are shorter with the bottom tips curving upwards, her eyes become red, and she has large white ornaments with red designs attached on her hairbands.", "[\"Nice To Meet You, Mr. Earthling\"]", DateTimeOffset.MinValue, DateTimeOffset.MinValue, 0 }
            });
    }

    /// <inheritdoc />
    protected override void Down(MigrationBuilder migrationBuilder)
    {
        migrationBuilder.DropTable(
            name: "MikuModules");
    }
